window.AVL_SOURCES = [{"label": "提交版（OJ 用）", "file": "interval_cover.py", "lang": "py", "stripped": "MODEL = \"point\"\n\nimport sys\n\nMAX_N = 1000\nMAX_M = 20\n\ndef make_reader():\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:\n                return None\n            buf.extend(reversed(line.split()))\n        return buf.pop()\n\n    return nxt\n\ndef min_length(x, m, model):\n    n = len(x)\n    x.sort()\n\n    if model == \"point\":\n\n        span = x[n - 1] - x[0]\n        gaps = [x[i + 1] - x[i] for i in range(n - 1)]\n    else:\n\n        span = x[n - 1] + 1 - x[0]\n        gaps = [x[i + 1] - x[i] - 1 for i in range(n - 1)]\n\n    gaps.sort(reverse=True)\n\n    k = m - 1\n    if k > n - 1:\n        k = n - 1\n    if k < 0:\n        k = 0\n\n    cut = 0\n    for i in range(k):\n        cut += gaps[i]\n\n    return span - cut\n\ndef to_int(tok):\n    try:\n        return int(tok)\n    except ValueError:\n        sys.stderr.write(\"[!] 非法输入（不是整数）: %s\\n\" % tok)\n        return None\n\ndef main():\n    nxt = make_reader()\n    case = 0\n\n    while True:\n        tok = nxt()\n        if tok is None:\n            return\n\n        n = to_int(tok)\n        if n is None:\n            return\n\n        if n < 1 or n > MAX_N:\n            sys.stderr.write(\"[!] n 越界: %s（应为 1 <= n <= %d，第 %d 组）\\n\"\n                             % (n, MAX_N, case + 1))\n            return\n\n        m = to_int(nxt())\n        if m is None:\n            sys.stderr.write(\"[!] 第 %d 组缺少 m（数据不足）\\n\" % (case + 1))\n            return\n\n        if m < 1 or m > MAX_M:\n            sys.stderr.write(\"[!] 提示：m=%s 超出题面上限（1 <= m <= %d），\"\n                             \"仍按原值计算\\n\" % (m, MAX_M))\n\n        case += 1\n\n        x = []\n        for _ in range(n):\n            t = nxt()\n            if t is None:\n                sys.stderr.write(\"[!] 第 %d 组数据不足：声明 n=%d，实际只读到 %d 个\\n\"\n                                 % (case, n, len(x)))\n                return\n            v = to_int(t)\n            if v is None:\n                return\n            x.append(v)\n\n        if len(set(x)) != n:\n\n            sys.stderr.write(\"[!] 提示：第 %d 组的 x 存在重复值（题面保证互不相同），\"\n                             \"结果可能不符预期\\n\" % case)\n\n        sys.stdout.write(\"%d\\n\" % min_length(x, m, MODEL))\n        sys.stdout.flush()\n\nif __name__ == \"__main__\":\n    main()\n", "original": "# -*- coding: utf-8 -*-\n#\n# 单位区间覆盖 —— OJ 提交版（stdout 只输出答案）\n# =============================================\n#\n# 输入：多组测试数据，每组 2 行\n#         第 1 行：n m    （n 个单位区间，至多用 m 条线段覆盖；1<=n<=1000，1<=m<=20）\n#         第 2 行：n 个互不相同的整数 x1..xn，表示这 n 个单位区间的**左端点**\n# 输出：每组一行 —— 覆盖这 n 个单位区间的至多 m 条线段总长度的最小值\n#\n# 样例：6 3 / 1 2 4 5 -2 6   ->   3   （见下面\"判题模型\"一节，本题唯一坑）\n#\n# 算法：排序 + 贪心\"剪最大的空隙\"  O(n log n)\n# ------------------------------------------\n# 先想只给 1 条线段的情形：要把全部单位区间都盖住，最左只能从 min(x) 起、\n# 最右必须到 max(x)+1（因为 [x_i, x_i+1] 是闭区间，右端点也要盖住），\n# 所以 1 条线段时总长 = max(x) + 1 - min(x)。\n#\n# 现在允许 m 条线段。把这 m 条线段看成\"在那一整根长条上剪 m-1 刀\"：\n# 每剪一刀，就把序列切成两段，**省掉该处的一段长度**。剪在哪儿最划算？\n# 当然是剪**最大的那几个空隙**。\n#\n# 空隙怎么算：排序后相邻两个单位区间 [x_i, x_i+1] 与 [x_{i+1}, x_{i+1}+1]\n# 之间真正空出来的距离是\n#         gap = x_{i+1} - x_i - 1\n# 若 x_{i+1} = x_i + 1，两个区间**接壤**（[1,2] 与 [2,3]），gap = 0，剪了不省。\n#\n# 于是：  答案 = (max(x) + 1 - min(x))  -  Σ(最大的 m-1 个 gap)\n#\n# 为什么贪心一定对（不是\"看着像\"）：\n#   * 总长 = (常数 span) - Σ(被剪开处的 gap)，其中 span 与剪法无关；\n#     所以\"总长最小\" <=> \"被剪掉的 gap 之和最大\"。\n#   * 可剪的位置只有 n-1 个（相邻两点之间），每个位置的 gap 是**固定的非负数**，\n#     且各剪点互相独立、不叠加（一刀只切一个位置）—— 这是标准的\"可加无交互\"结构，\n#     于是取最大的 m-1 个就是最优，交换论证即可：若某个较大的 gap 没被剪而较小的被剪了，\n#     把那把刀挪到较大 gap 处，总长只会更小，矛盾。\n#   * 分组必须**连续**（一条线段覆盖一段连续的区间）：若某组跳过了中间的区间，\n#     被跳过的那些要么得由别的线段覆盖（线段重叠，总长不会更短），\n#     要么就是没盖住（非法）。所以最优解一定对应\"切成连续的至多 m 段\"。\n#\n# 边界：\n#   * m >= n 时，一刀一刀剪完所有空隙，答案 = n（每个单位区间各用 1 条长度 1 的线段）。\n#     公式自动成立（k 被夹到 n-1），不用特判。\n#   * n = 1 时没有空隙，答案 = 1。\n#\n# 判题口径开关（★ 本题唯一的坑，务必先读）\n# ---------------------------------------\n# 题面正文写的是「单位区间 [x_i, x_i+1]」，可题面自己给的样例\n#         输入  6 3 / 1 2 4 5 -2 6        输出  3\n# 按「单位区间」算出来是 6，按「点」算才是 3 —— 题面正文和它自己的样例对不上。\n# （题面输出段的原文写的是\"覆盖这 n 个点\"，可见作者自己也在两种说法之间摇摆。）\n#\n# ★ 已实测确认：这组数据 OJ 要的是 **3**，也就是判「点」口径 —— 所以默认设为 \"point\"。\n#   两个口径只差两处 ±1，开关留着只为方便对照：\n#\n#   \"point\"（默认）—— OJ 口径：span = max-min，gap = 相邻坐标差\n#                      本样例得 3；m >= n 时答案为 0\n#   \"interval\"      —— 题面正文字面口径：span = max+1-min，gap = 相邻坐标差 - 1\n#                      本样例得 6（与样例输出不符，别用这个交）\nMODEL = \"point\"\n\nimport sys\n\nMAX_N = 1000                      # 题面上限 1 <= n <= 1000\nMAX_M = 20                        # 题面上限 1 <= m <= 20\n\n\ndef make_reader():\n    \"\"\"返回一个取 token 的函数 nxt()，取完返回 None。\n\n    统一 readline() 逐行读 —— 终端 / PyCharm / OJ 三种环境都对：\n      * 不用 sys.stdin.read()：它要读到 EOF 才返回，终端里敲完数据毫无反应，像卡死；\n      * 也不用 isatty() 分流：PyCharm 运行窗口的 stdin 不是真 tty，\n        isatty() 返回 False 又会退回 read() 那条死路（此坑本仓库已踩两次）。\n\n    注意 取 token 用「反序入栈 + pop()」，**不写 pop(0)**：\n       pop(0) 每次 memmove 整个缓冲，若几十万个 token 挤在同一行，\n       读取退化成 O(k^2)（实测 10 万 token 挤一行要 28.8s，逐行喂只要 0.147s）→ TLE。\n       reversed() 先倒着存、pop() 从尾巴取，顺序不变，单次 O(1)。\n    \"\"\"\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:                          # EOF / Ctrl+Z\n                return None\n            buf.extend(reversed(line.split()))\n        return buf.pop()\n\n    return nxt\n\n\ndef min_length(x, m, model):\n    \"\"\"覆盖全部单位区间、至多用 m 条线段时的最小总长度。时间 O(n log n)。\"\"\"\n    n = len(x)\n    x.sort()\n\n    if model == \"point\":\n        # 按点：跨度 = max-min，空隙 = 相邻坐标差\n        span = x[n - 1] - x[0]\n        gaps = [x[i + 1] - x[i] for i in range(n - 1)]\n    else:\n        # 按单位区间：跨度 = max+1-min，空隙 = 相邻坐标差 - 1\n        span = x[n - 1] + 1 - x[0]\n        gaps = [x[i + 1] - x[i] - 1 for i in range(n - 1)]\n\n    gaps.sort(reverse=True)                       # 大空隙在前，好剪\n\n    k = m - 1                                     # 最多剪 m-1 刀\n    if k > n - 1:                                 # 只有 n-1 个位置可剪\n        k = n - 1\n    if k < 0:\n        k = 0\n\n    cut = 0\n    for i in range(k):\n        cut += gaps[i]\n\n    return span - cut\n\n\ndef to_int(tok):\n    \"\"\"token -> int；失败时按仓库规范打 [!] 到 stderr 并返回 None。\"\"\"\n    try:\n        return int(tok)\n    except ValueError:\n        sys.stderr.write(\"[!] 非法输入（不是整数）: %s\\n\" % tok)\n        return None\n\n\ndef main():\n    nxt = make_reader()\n    case = 0\n\n    while True:\n        tok = nxt()\n        if tok is None:                           # 正常结束：读到 EOF\n            return\n\n        n = to_int(tok)\n        if n is None:\n            return\n\n        # 铁律 6：n 决定后面还要吃掉多少 token，越界**宁可中止也不能错答**。\n        # 一旦 continue，后面的数字会被当成下一组的 n，把伪答案打进 stdout。\n        if n < 1 or n > MAX_N:\n            sys.stderr.write(\"[!] n 越界: %s（应为 1 <= n <= %d，第 %d 组）\\n\"\n                             % (n, MAX_N, case + 1))\n            return\n\n        m = to_int(nxt())\n        if m is None:\n            sys.stderr.write(\"[!] 第 %d 组缺少 m（数据不足）\\n\" % (case + 1))\n            return\n\n        # m 越界**只警告不中止**：m 不决定 token 流，中止会连累后面的组。\n        # 算法对任意 m >= 1 都成立（k 会被夹到 n-1），m > 20 只是超出题面上限而已。\n        if m < 1 or m > MAX_M:\n            sys.stderr.write(\"[!] 提示：m=%s 超出题面上限（1 <= m <= %d），\"\n                             \"仍按原值计算\\n\" % (m, MAX_M))\n\n        case += 1\n\n        x = []\n        for _ in range(n):\n            t = nxt()\n            if t is None:\n                sys.stderr.write(\"[!] 第 %d 组数据不足：声明 n=%d，实际只读到 %d 个\\n\"\n                                 % (case, n, len(x)))\n                return\n            v = to_int(t)\n            if v is None:\n                return\n            x.append(v)\n\n        if len(set(x)) != n:\n            # 题面保证 x 互不相同。真出现重复说明数据不合规矩，\n            # 公式会算错（区间模型下 gap 会变成 -1），必须让人看得见。\n            sys.stderr.write(\"[!] 提示：第 %d 组的 x 存在重复值（题面保证互不相同），\"\n                             \"结果可能不符预期\\n\" % case)\n\n        sys.stdout.write(\"%d\\n\" % min_length(x, m, MODEL))\n        sys.stdout.flush()                        # 每组输出立刻刷出\n\n\nif __name__ == \"__main__\":\n    main()\n"}, {"label": "详细版（本地学习）", "file": "interval_cover_detailed.py", "lang": "py", "stripped": "MODEL = \"point\"\n\nimport sys\n\nfrom itertools import combinations\n\ndef make_reader():\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:\n                return None\n            buf.extend(reversed(line.split()))\n        return buf.pop()\n\n    return nxt\n\ndef gaps_of(xs, model):\n    out = []\n    for i in range(len(xs) - 1):\n        if model == \"point\":\n            out.append(xs[i + 1] - xs[i])\n        else:\n            out.append(xs[i + 1] - xs[i] - 1)\n    return out\n\ndef solve_verbose(x, m, model, case):\n    xs = sorted(x)\n    n = len(xs)\n    model_name = \"point\" if model == \"point\" else \"interval\"\n\n    print(\"=\" * 66)\n    print(\"第 %d 组：n = %d，m = %d（模型 = %s）\" % (case, n, m, model_name))\n    print(\"=\" * 66)\n\n    print(\"  原始 x  : \" + \" \".join(str(v) for v in x))\n    print(\"  排序后  : \" + \" \".join(str(v) for v in xs))\n    print(\"  单位区间: \" + \"、\".join(\"[%d,%d]\" % (v, v + 1) for v in xs))\n    if model == \"point\":\n        print(\"  说明    : 按【点】口径 —— 每个 x 当作一个点，线段长度 = 两端坐标之差\")\n    else:\n        print(\"  说明    : 按【单位区间】口径 —— 左端点 x，右端点 x+1，线段要盖住整段\")\n\n    if model == \"point\":\n        span = xs[n - 1] - xs[0]\n        span_desc = \"%d - (%d) = %d\" % (xs[n - 1], xs[0], span) if xs[0] < 0 \\\n            else \"%d - %d = %d\" % (xs[n - 1], xs[0], span)\n    else:\n        span = xs[n - 1] + 1 - xs[0]\n        span_desc = \"(%d + 1) - (%d) = %d\" % (xs[n - 1], xs[0], span) if xs[0] < 0 \\\n            else \"(%d + 1) - %d = %d\" % (xs[n - 1], xs[0], span)\n\n    print(\"\")\n    print(\"第 1 步：只用 1 条线段，必须从最左盖到最右\")\n    print(\"        跨度 span = \" + span_desc)\n\n    gaps = gaps_of(xs, model)\n    print(\"\")\n    print(\"第 2 步：相邻单位区间之间的空隙（剪开一处就省掉这一段长度）\")\n    if n == 1:\n        print(\"        只有 1 个单位区间，没有空隙可剪\")\n    else:\n        for i in range(n - 1):\n            left_desc = \"[%d,%d]\" % (xs[i], xs[i] + 1)\n            right_desc = \"[%d,%d]\" % (xs[i + 1], xs[i + 1] + 1)\n            if model == \"point\":\n                why = \"%d - %d\" % (xs[i + 1], xs[i])\n            elif xs[i] < 0:\n                why = \"%d - (%d) - 1\" % (xs[i + 1], xs[i])\n            else:\n                why = \"%d - %d - 1\" % (xs[i + 1], xs[i])\n            if gaps[i] == 0:\n                note = \"   <- 接壤，剪了也不省\"\n            else:\n                note = \"\"\n            print(\"        位置 %d|%d  %s ~ %s   gap = %s = %d%s\"\n                  % (i, i + 1, left_desc, right_desc, why, gaps[i], note))\n\n    order = sorted(range(len(gaps)), key=lambda i: (-gaps[i], i))\n    cuts = min(m - 1, n - 1)\n    if cuts < 0:\n        cuts = 0\n    chosen = sorted(order[:cuts])\n\n    print(\"\")\n    print(\"第 3 步：最多能剪 %d 刀（m-1 = %d，但只有 %d 个位置可剪）\"\n          % (cuts, m - 1, max(n - 1, 0)))\n    if cuts == 0:\n        print(\"        一刀都不剪：直接用 1 条线段盖住全部\")\n    else:\n        picked = [gaps[i] for i in chosen]\n        print(\"        按空隙从大到小挑：\"\n              + \"、\".join(str(v) for v in picked)\n              + \"（剪在位置 \" + \"、\".join(str(i) for i in chosen) + \" 处）\")\n        if len(gaps) > cuts:\n            rest = sorted((gaps[i] for i in range(len(gaps)) if i not in chosen),\n                          reverse=True)\n            if rest:\n                print(\"        剩下的空隙不剪：\" + \"、\".join(str(v) for v in rest))\n\n    cut_sum = 0\n    for i in chosen:\n        cut_sum += gaps[i]\n\n    print(\"\")\n    print(\"        1 条线段的长度 span      = %d\" % span)\n    print(\"        剪掉的总空隙 -Σgap       = %d\" % cut_sum)\n    print(\"        总长度 = span - Σgap     = %d\" % (span - cut_sum))\n\n    bounds = [0]\n    for i in chosen:\n        bounds.append(i + 1)\n    bounds.append(n)\n\n    print(\"\")\n    print(\"第 4 步：实际方案（共 %d 条线段，要求 <= m = %d）\" % (len(bounds) - 1, m))\n    plan = []\n    total_len = 0\n    for t in range(len(bounds) - 1):\n        l = bounds[t]\n        r = bounds[t + 1] - 1\n        left = xs[l]\n        if model == \"point\":\n\n            right = xs[r]\n            length = right - left\n            covered = \"、\".join(str(xs[i]) for i in range(l, r + 1))\n            verb = \"盖住点\"\n        else:\n\n            right = xs[r] + 1\n            length = right - left\n            covered = \"、\".join(\"[%d,%d]\" % (xs[i], xs[i] + 1) for i in range(l, r + 1))\n            verb = \"覆盖\"\n        print(\"        线段 %d: [%d, %d]  长 %d   %s %s\"\n              % (t + 1, left, right, length, verb, covered))\n        plan.append((l, r))\n        total_len += length\n\n    ans = span - cut_sum\n\n    print(\"\")\n    print(\"  --- 自校 (Sum check) ---\")\n    ok1 = (total_len == ans)\n    print(\"    ① Σ各线段长度 = %d，公式算出的答案 = %d   %s\"\n          % (total_len, ans, \"OK\" if ok1 else \"*** 不符 ***\"))\n\n    ok2 = True\n    for (l, r) in plan:\n        if model == \"point\":\n            left, right = xs[l], xs[r]\n            for i in range(l, r + 1):\n                if not (left <= xs[i] <= right):\n                    ok2 = False\n        else:\n            left, right = xs[l], xs[r] + 1\n            for i in range(l, r + 1):\n                if not (left <= xs[i] and xs[i] + 1 <= right):\n                    ok2 = False\n    print(\"    ② 每条线段完整覆盖组内全部%s        %s\"\n          % (\"点\" if model == \"point\" else \"单位区间\",\n             \"OK\" if ok2 else \"*** 有东西没被盖住 ***\"))\n\n    ok3 = (len(plan) <= m)\n    print(\"    ③ 线段条数 %d <= m = %d                  %s\"\n          % (len(plan), m, \"OK\" if ok3 else \"*** 超了 ***\"))\n\n    ok4 = True\n    all_covered = [0] * n\n    for (l, r) in plan:\n        for i in range(l, r + 1):\n            all_covered[i] += 1\n    if all_covered != [1] * n:\n        ok4 = False\n    print(\"    ④ 每%s恰好被 1 条线段覆盖            %s\"\n          % (\"个点\" if model == \"point\" else \"个单位区间\",\n             \"OK\" if ok4 else \"*** 有重复或遗漏 ***\"))\n\n    if model != \"point\":\n        ok5 = (ans >= n)\n        print(\"    ⑤ 答案 %d >= n = %d（并集测度下界）      %s\"\n              % (ans, n, \"OK\" if ok5 else \"*** 破了下界 ***\"))\n    else:\n        ok5 = (ans >= 0)\n        print(\"    ⑤ 答案 %d >= 0                        %s\"\n              % (ans, \"OK\" if ok5 else \"*** 破了下界 ***\"))\n\n    if n <= 12:\n        bf = brute_groups(xs, m, model)\n        ok6 = (bf == ans)\n        print(\"    ⑥ 独立暴力复核：枚举所有分组得 %d            %s\"\n              % (bf, \"OK\" if ok6 else \"*** 答案不是最优 ***\"))\n    else:\n        ok6 = True\n        print(\"    ⑥ n = %d > 12，跳过暴力复核（组合数会爆炸）\" % n)\n\n    all_ok = ok1 and ok2 and ok3 and ok4 and ok5 and ok6\n\n    print(\"\")\n    print(\"  答案 = %d%s\" % (ans, \"\" if all_ok else \"   *** 自校没过，请检查 ***\"))\n\n    other = \"point\" if model != \"point\" else \"interval\"\n    other_ans = solve_other(x, m, other)\n    print(\"  （对照：若按 %s 口径，本题答案是 %d）\" % (other, other_ans))\n    print(\"\")\n\n    return ans, plan, all_ok\n\ndef brute_groups(xs, m, model):\n    n = len(xs)\n    best = None\n    for g in range(1, min(m, n) + 1):\n        for cuts in combinations(range(1, n), g - 1):\n            b = (0,) + cuts + (n,)\n            total = 0\n            for t in range(len(b) - 1):\n                l = b[t]\n                r = b[t + 1] - 1\n                if model == \"point\":\n                    total += xs[r] - xs[l]\n                else:\n                    total += xs[r] + 1 - xs[l]\n            if best is None or total < best:\n                best = total\n    return best\n\ndef solve_other(x, m, model):\n    xs = sorted(x)\n    n = len(xs)\n    if model == \"point\":\n        span = xs[n - 1] - xs[0]\n        gaps = [xs[i + 1] - xs[i] for i in range(n - 1)]\n    else:\n        span = xs[n - 1] + 1 - xs[0]\n        gaps = [xs[i + 1] - xs[i] - 1 for i in range(n - 1)]\n    gaps.sort(reverse=True)\n    k = m - 1\n    if k > n - 1:\n        k = n - 1\n    if k < 0:\n        k = 0\n    cut = 0\n    for i in range(k):\n        cut += gaps[i]\n    return span - cut\n\ndef main():\n    nxt = make_reader()\n    case = 0\n    all_ok = True\n\n    while True:\n        tok = nxt()\n        if tok is None:\n            break\n\n        try:\n            n = int(tok)\n        except ValueError:\n            sys.stderr.write(\"[!] 非法输入（n 不是整数）: %s\\n\" % tok)\n            return\n\n        if n < 1 or n > 1000:\n            sys.stderr.write(\"[!] n 越界: %d（应为 1 <= n <= 1000）\\n\" % n)\n            return\n\n        t = nxt()\n        if t is None:\n            sys.stderr.write(\"[!] 数据不足：缺少 m\\n\")\n            return\n        try:\n            m = int(t)\n        except ValueError:\n            sys.stderr.write(\"[!] 非法输入（m 不是整数）: %s\\n\" % t)\n            return\n        if m < 1 or m > 20:\n            sys.stderr.write(\"[!] 提示：m=%d 超出题面上限（1 <= m <= 20），仍按原值计算\\n\" % m)\n\n        case += 1\n\n        x = []\n        for _ in range(n):\n            t = nxt()\n            if t is None:\n                sys.stderr.write(\"[!] 数据不足：声明 n=%d，实际只读到 %d 个\\n\" % (n, len(x)))\n                return\n            try:\n                x.append(int(t))\n            except ValueError:\n                sys.stderr.write(\"[!] 非法输入（x 不是整数）: %s\\n\" % t)\n                return\n\n        if len(set(x)) != n:\n            sys.stderr.write(\"[!] 提示：第 %d 组的 x 存在重复值\\n\" % case)\n\n        ans, plan, ok = solve_verbose(x, m, MODEL, case)\n        if not ok:\n            all_ok = False\n\n    if not all_ok:\n        sys.stderr.write(\"[!] 有分组自校未通过\\n\")\n\nif __name__ == \"__main__\":\n    main()\n", "original": "# -*- coding: utf-8 -*-\n#\n# 单位区间覆盖 —— 详细版（**仅供本地学习，勿提交 OJ**）\n# ======================================================\n#\n# 极简版只吐一个数；这一版把中间过程全摊开：\n#   * 排序前后的坐标\n#   * 相邻两个单位区间之间的**每一处空隙**（并标出哪些被\"剪\"了）\n#   * 最终方案：每组用哪条线段、多长\n#   * 自校（Sum check）：三段独立算出来的数字必须对上\n#\n# 算法见 interval_cover.py 的文件头（排序 + 贪心剪最大空隙，O(n log n)）。\n# 这一版只是把同一套逻辑讲出声音来，算法本体一字不改。\n#\n# 判题口径开关（与极简版同一个坑）。已实测确认 OJ 判「点」口径（样例要 3），故默认 point：\n#   \"point\"（默认）—— span = max-min，  gap = 相邻坐标差       （OJ 口径；本样例得 3）\n#   \"interval\"      —— span = max+1-min，gap = 相邻坐标差 - 1   （题面正文字面；本样例得 6）\nMODEL = \"point\"\n\nimport sys\n\nfrom itertools import combinations\n\n\ndef make_reader():\n    \"\"\"逐行 readline() 取 token；反序入栈 + pop()，单次 O(1)。\n\n    细节见 interval_cover.py 的同名函数。终端 / PyCharm / OJ 三环境通用。\n    \"\"\"\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:                              # EOF / Ctrl+Z\n                return None\n            buf.extend(reversed(line.split()))\n        return buf.pop()\n\n    return nxt\n\n\ndef gaps_of(xs, model):\n    \"\"\"返回相邻单位区间之间的空隙列表（长度为 n-1）。\n\n    interval 口径：gap = x[i+1] - x[i] - 1\n        两个区间 [1,2] 与 [2,3] 是**接壤**的，中间真正空出来 0 的距离。\n    point 口径：gap = x[i+1] - x[i]\n    \"\"\"\n    out = []\n    for i in range(len(xs) - 1):\n        if model == \"point\":\n            out.append(xs[i + 1] - xs[i])\n        else:\n            out.append(xs[i + 1] - xs[i] - 1)\n    return out\n\n\ndef solve_verbose(x, m, model, case):\n    \"\"\"跑一遍并打印全过程，返回 (答案, 分组方案)。\n\n    分组方案 plan 形如 [(l, r), ...]：第 k 组覆盖排序后的 x[l..r]（闭区间）。\n    \"\"\"\n    xs = sorted(x)\n    n = len(xs)\n    model_name = \"point\" if model == \"point\" else \"interval\"\n\n    print(\"=\" * 66)\n    print(\"第 %d 组：n = %d，m = %d（模型 = %s）\" % (case, n, m, model_name))\n    print(\"=\" * 66)\n\n    print(\"  原始 x  : \" + \" \".join(str(v) for v in x))\n    print(\"  排序后  : \" + \" \".join(str(v) for v in xs))\n    print(\"  单位区间: \" + \"、\".join(\"[%d,%d]\" % (v, v + 1) for v in xs))\n    if model == \"point\":\n        print(\"  说明    : 按【点】口径 —— 每个 x 当作一个点，线段长度 = 两端坐标之差\")\n    else:\n        print(\"  说明    : 按【单位区间】口径 —— 左端点 x，右端点 x+1，线段要盖住整段\")\n\n    # ---------- 第 1 步：只用 1 条线段要多长 ----------\n    if model == \"point\":\n        span = xs[n - 1] - xs[0]\n        span_desc = \"%d - (%d) = %d\" % (xs[n - 1], xs[0], span) if xs[0] < 0 \\\n            else \"%d - %d = %d\" % (xs[n - 1], xs[0], span)\n    else:\n        span = xs[n - 1] + 1 - xs[0]\n        span_desc = \"(%d + 1) - (%d) = %d\" % (xs[n - 1], xs[0], span) if xs[0] < 0 \\\n            else \"(%d + 1) - %d = %d\" % (xs[n - 1], xs[0], span)\n\n    print(\"\")\n    print(\"第 1 步：只用 1 条线段，必须从最左盖到最右\")\n    print(\"        跨度 span = \" + span_desc)\n\n    # ---------- 第 2 步：看看有哪些空隙可以剪 ----------\n    gaps = gaps_of(xs, model)\n    print(\"\")\n    print(\"第 2 步：相邻单位区间之间的空隙（剪开一处就省掉这一段长度）\")\n    if n == 1:\n        print(\"        只有 1 个单位区间，没有空隙可剪\")\n    else:\n        for i in range(n - 1):\n            left_desc = \"[%d,%d]\" % (xs[i], xs[i] + 1)\n            right_desc = \"[%d,%d]\" % (xs[i + 1], xs[i + 1] + 1)\n            if model == \"point\":\n                why = \"%d - %d\" % (xs[i + 1], xs[i])\n            elif xs[i] < 0:\n                why = \"%d - (%d) - 1\" % (xs[i + 1], xs[i])\n            else:\n                why = \"%d - %d - 1\" % (xs[i + 1], xs[i])\n            if gaps[i] == 0:\n                note = \"   <- 接壤，剪了也不省\"\n            else:\n                note = \"\"\n            print(\"        位置 %d|%d  %s ~ %s   gap = %s = %d%s\"\n                  % (i, i + 1, left_desc, right_desc, why, gaps[i], note))\n\n    # ---------- 第 3 步：剪最大的 m-1 刀 ----------\n    order = sorted(range(len(gaps)), key=lambda i: (-gaps[i], i))\n    cuts = min(m - 1, n - 1)\n    if cuts < 0:\n        cuts = 0\n    chosen = sorted(order[:cuts])\n\n    print(\"\")\n    print(\"第 3 步：最多能剪 %d 刀（m-1 = %d，但只有 %d 个位置可剪）\"\n          % (cuts, m - 1, max(n - 1, 0)))\n    if cuts == 0:\n        print(\"        一刀都不剪：直接用 1 条线段盖住全部\")\n    else:\n        picked = [gaps[i] for i in chosen]\n        print(\"        按空隙从大到小挑：\"\n              + \"、\".join(str(v) for v in picked)\n              + \"（剪在位置 \" + \"、\".join(str(i) for i in chosen) + \" 处）\")\n        if len(gaps) > cuts:\n            rest = sorted((gaps[i] for i in range(len(gaps)) if i not in chosen),\n                          reverse=True)\n            if rest:\n                print(\"        剩下的空隙不剪：\" + \"、\".join(str(v) for v in rest))\n\n    cut_sum = 0\n    for i in chosen:\n        cut_sum += gaps[i]\n\n    print(\"\")\n    print(\"        1 条线段的长度 span      = %d\" % span)\n    print(\"        剪掉的总空隙 -Σgap       = %d\" % cut_sum)\n    print(\"        总长度 = span - Σgap     = %d\" % (span - cut_sum))\n\n    # ---------- 第 4 步：把方案摆出来 ----------\n    bounds = [0]\n    for i in chosen:\n        bounds.append(i + 1)\n    bounds.append(n)\n\n    print(\"\")\n    print(\"第 4 步：实际方案（共 %d 条线段，要求 <= m = %d）\" % (len(bounds) - 1, m))\n    plan = []\n    total_len = 0\n    for t in range(len(bounds) - 1):\n        l = bounds[t]\n        r = bounds[t + 1] - 1\n        left = xs[l]\n        if model == \"point\":\n            # 点口径：线段只要盖住组内这几个**点**，右端到 xs[r] 为止\n            right = xs[r]\n            length = right - left\n            covered = \"、\".join(str(xs[i]) for i in range(l, r + 1))\n            verb = \"盖住点\"\n        else:\n            # 单位区间口径：右端点要盖住最后一个区间的右端，即 x+1\n            right = xs[r] + 1\n            length = right - left\n            covered = \"、\".join(\"[%d,%d]\" % (xs[i], xs[i] + 1) for i in range(l, r + 1))\n            verb = \"覆盖\"\n        print(\"        线段 %d: [%d, %d]  长 %d   %s %s\"\n              % (t + 1, left, right, length, verb, covered))\n        plan.append((l, r))\n        total_len += length\n\n    ans = span - cut_sum\n\n    # ---------- 自校（Sum check） ----------\n    print(\"\")\n    print(\"  --- 自校 (Sum check) ---\")\n    ok1 = (total_len == ans)\n    print(\"    ① Σ各线段长度 = %d，公式算出的答案 = %d   %s\"\n          % (total_len, ans, \"OK\" if ok1 else \"*** 不符 ***\"))\n\n    # ② 每条线段都要真的盖住自己那组的每一个区间（点口径下则是盖住每一个点）\n    ok2 = True\n    for (l, r) in plan:\n        if model == \"point\":\n            left, right = xs[l], xs[r]\n            for i in range(l, r + 1):\n                if not (left <= xs[i] <= right):\n                    ok2 = False\n        else:\n            left, right = xs[l], xs[r] + 1\n            for i in range(l, r + 1):\n                if not (left <= xs[i] and xs[i] + 1 <= right):\n                    ok2 = False\n    print(\"    ② 每条线段完整覆盖组内全部%s        %s\"\n          % (\"点\" if model == \"point\" else \"单位区间\",\n             \"OK\" if ok2 else \"*** 有东西没被盖住 ***\"))\n\n    ok3 = (len(plan) <= m)\n    print(\"    ③ 线段条数 %d <= m = %d                  %s\"\n          % (len(plan), m, \"OK\" if ok3 else \"*** 超了 ***\"))\n\n    ok4 = True\n    all_covered = [0] * n\n    for (l, r) in plan:\n        for i in range(l, r + 1):\n            all_covered[i] += 1\n    if all_covered != [1] * n:\n        ok4 = False\n    print(\"    ④ 每%s恰好被 1 条线段覆盖            %s\"\n          % (\"个点\" if model == \"point\" else \"个单位区间\",\n             \"OK\" if ok4 else \"*** 有重复或遗漏 ***\"))\n\n    if model != \"point\":\n        ok5 = (ans >= n)\n        print(\"    ⑤ 答案 %d >= n = %d（并集测度下界）      %s\"\n              % (ans, n, \"OK\" if ok5 else \"*** 破了下界 ***\"))\n    else:\n        ok5 = (ans >= 0)\n        print(\"    ⑤ 答案 %d >= 0                        %s\"\n              % (ans, \"OK\" if ok5 else \"*** 破了下界 ***\"))\n\n    # ⑥ ★ 最优性复核。上面 ①-④ 验的只是\"账目自洽\"——\n    #   曾经把「剪最小空隙」这个错注入进去，① 的 Σ段长 == 答案 **照样成立**\n    #   （9 == 5+2+2），四条自校全绿却给出了错误答案。\n    #   所以小规模时直接枚举所有分组，拿真正的最优值来对。\n    if n <= 12:\n        bf = brute_groups(xs, m, model)\n        ok6 = (bf == ans)\n        print(\"    ⑥ 独立暴力复核：枚举所有分组得 %d            %s\"\n              % (bf, \"OK\" if ok6 else \"*** 答案不是最优 ***\"))\n    else:\n        ok6 = True\n        print(\"    ⑥ n = %d > 12，跳过暴力复核（组合数会爆炸）\" % n)\n\n    all_ok = ok1 and ok2 and ok3 and ok4 and ok5 and ok6\n\n    # ---------- 答案 ----------\n    print(\"\")\n    print(\"  答案 = %d%s\" % (ans, \"\" if all_ok else \"   *** 自校没过，请检查 ***\"))\n\n    # 另一口径的答案，供对照（题面与样例互相矛盾，两种口径都摆出来最省心）\n    other = \"point\" if model != \"point\" else \"interval\"\n    other_ans = solve_other(x, m, other)\n    print(\"  （对照：若按 %s 口径，本题答案是 %d）\" % (other, other_ans))\n    print(\"\")\n\n    return ans, plan, all_ok\n\n\ndef brute_groups(xs, m, model):\n    \"\"\"枚举所有「切成至多 m 段连续组」的方式，返回最小总长。\n\n    完全独立于贪心：不推理、不剪空隙，就是把所有切法试一遍。\n    只在小 n（<= 12）时调用，C(11,5) 这个量级还是毫秒级。\n    \"\"\"\n    n = len(xs)\n    best = None\n    for g in range(1, min(m, n) + 1):\n        for cuts in combinations(range(1, n), g - 1):\n            b = (0,) + cuts + (n,)\n            total = 0\n            for t in range(len(b) - 1):\n                l = b[t]\n                r = b[t + 1] - 1\n                if model == \"point\":\n                    total += xs[r] - xs[l]\n                else:\n                    total += xs[r] + 1 - xs[l]\n            if best is None or total < best:\n                best = total\n    return best\n\n\ndef solve_other(x, m, model):\n    \"\"\"只求值、不打印，用于给出\"另一口径\"的答案做对照。\"\"\"\n    xs = sorted(x)\n    n = len(xs)\n    if model == \"point\":\n        span = xs[n - 1] - xs[0]\n        gaps = [xs[i + 1] - xs[i] for i in range(n - 1)]\n    else:\n        span = xs[n - 1] + 1 - xs[0]\n        gaps = [xs[i + 1] - xs[i] - 1 for i in range(n - 1)]\n    gaps.sort(reverse=True)\n    k = m - 1\n    if k > n - 1:\n        k = n - 1\n    if k < 0:\n        k = 0\n    cut = 0\n    for i in range(k):\n        cut += gaps[i]\n    return span - cut\n\n\ndef main():\n    nxt = make_reader()\n    case = 0\n    all_ok = True\n\n    while True:\n        tok = nxt()\n        if tok is None:\n            break\n\n        try:\n            n = int(tok)\n        except ValueError:\n            sys.stderr.write(\"[!] 非法输入（n 不是整数）: %s\\n\" % tok)\n            return\n\n        if n < 1 or n > 1000:\n            sys.stderr.write(\"[!] n 越界: %d（应为 1 <= n <= 1000）\\n\" % n)\n            return\n\n        t = nxt()\n        if t is None:\n            sys.stderr.write(\"[!] 数据不足：缺少 m\\n\")\n            return\n        try:\n            m = int(t)\n        except ValueError:\n            sys.stderr.write(\"[!] 非法输入（m 不是整数）: %s\\n\" % t)\n            return\n        if m < 1 or m > 20:\n            sys.stderr.write(\"[!] 提示：m=%d 超出题面上限（1 <= m <= 20），仍按原值计算\\n\" % m)\n\n        case += 1\n\n        x = []\n        for _ in range(n):\n            t = nxt()\n            if t is None:\n                sys.stderr.write(\"[!] 数据不足：声明 n=%d，实际只读到 %d 个\\n\" % (n, len(x)))\n                return\n            try:\n                x.append(int(t))\n            except ValueError:\n                sys.stderr.write(\"[!] 非法输入（x 不是整数）: %s\\n\" % t)\n                return\n\n        if len(set(x)) != n:\n            sys.stderr.write(\"[!] 提示：第 %d 组的 x 存在重复值\\n\" % case)\n\n        ans, plan, ok = solve_verbose(x, m, MODEL, case)\n        if not ok:\n            all_ok = False\n\n        # 详细版的整块 stdout 已经是给人看的，这里不再额外打印答案行。\n\n    if not all_ok:\n        sys.stderr.write(\"[!] 有分组自校未通过\\n\")\n\n\nif __name__ == \"__main__\":\n    main()\n"}, {"label": "C 实现", "file": "interval_cover.c", "lang": "c", "stripped": "#include <stdio.h>\n#include <stdlib.h>\n\n\n#define MODEL_INTERVAL 0\n\n#define MAX_N 1000\n#define MAX_M 20\n\nstatic long long xs[MAX_N];\nstatic long long gaps[MAX_N];\n\n\nstatic int read_int(long long *out)\n{\n    int c;\n    int neg = 0;\n    int got = 0;\n    long long v = 0;\n\n\n    do {\n        c = getchar();\n    } while (c == ' ' || c == '\\t' || c == '\\n' || c == '\\r' ||\n             c == '\\f' || c == '\\v');\n\n    if (c == EOF) {\n        return 0;\n    }\n    if (c == '-') {\n        neg = 1;\n        c = getchar();\n    } else if (c == '+') {\n        c = getchar();\n    }\n\n    while (c >= '0' && c <= '9') {\n        v = v * 10 + (c - '0');\n        got = 1;\n        c = getchar();\n    }\n\n    if (!got) {\n\n\n        return -1;\n    }\n    if (c != EOF) {\n        ungetc(c, stdin);\n    }\n    *out = neg ? -v : v;\n    return 1;\n}\n\n\nstatic int cmp_ll_asc(const void *a, const void *b)\n{\n    long long x = *(const long long *)a;\n    long long y = *(const long long *)b;\n    if (x < y) return -1;\n    if (x > y) return 1;\n    return 0;\n}\n\n\nstatic int cmp_ll_desc(const void *a, const void *b)\n{\n    long long x = *(const long long *)a;\n    long long y = *(const long long *)b;\n    if (x > y) return -1;\n    if (x < y) return 1;\n    return 0;\n}\n\nint main(void)\n{\n    long long n_ll, m_ll;\n    int rc;\n\n    while ((rc = read_int(&n_ll)) == 1) {\n        int i;\n        int n, m, k;\n        long long span, cut;\n\n\n        if (n_ll < 1 || n_ll > MAX_N) {\n            fprintf(stderr, \"[!] n 越界: %lld（应为 1 <= n <= %d）\\n\", n_ll, MAX_N);\n            return 0;\n        }\n\n        if (read_int(&m_ll) != 1) {\n            fprintf(stderr, \"[!] 数据不足：缺少 m\\n\");\n            return 0;\n        }\n\n\n        if (m_ll < 1 || m_ll > MAX_M) {\n            fprintf(stderr, \"[!] 提示：m=%lld 超出题面上限（1 <= m <= %d），\"\n                            \"仍按原值计算\\n\", m_ll, MAX_M);\n        }\n\n        n = (int)n_ll;\n        m = (int)m_ll;\n\n        for (i = 0; i < n; i++) {\n            long long v;\n            if (read_int(&v) != 1) {\n                fprintf(stderr, \"[!] 数据不足：声明 n=%d，实际只读到 %d 个\\n\", n, i);\n                return 0;\n            }\n            xs[i] = v;\n        }\n\n        qsort(xs, (size_t)n, sizeof(long long), cmp_ll_asc);\n\n#if MODEL_INTERVAL\n        span = xs[n - 1] + 1 - xs[0];\n        for (i = 0; i < n - 1; i++) {\n            gaps[i] = xs[i + 1] - xs[i] - 1;\n        }\n#else\n        span = xs[n - 1] - xs[0];\n        for (i = 0; i < n - 1; i++) {\n            gaps[i] = xs[i + 1] - xs[i];\n        }\n#endif\n\n        if (n > 1) {\n            qsort(gaps, (size_t)(n - 1), sizeof(long long), cmp_ll_desc);\n        }\n\n        k = m - 1;\n        if (k > n - 1) {\n            k = n - 1;\n        }\n        if (k < 0) {\n            k = 0;\n        }\n\n        cut = 0;\n        for (i = 0; i < k; i++) {\n            cut += gaps[i];\n        }\n\n        printf(\"%lld\\n\", span - cut);\n        fflush(stdout);\n    }\n\n    if (rc == -1) {\n        fprintf(stderr, \"[!] 非法输入（读到了不是整数的 token）\\n\");\n        return 0;\n    }\n    return 0;\n}\n", "original": "/*\n * 单位区间覆盖 —— C 实现（OJ 兼容性通常比 Python 好）\n * ===================================================\n *\n * ⚠ 本机（Windows）**没有装任何 C 编译器**（gcc / clang / tcc / cl / zig 全无，\n *   PATH 和常见安装位置都搜过了）。所以这份代码**从未被编译验证过**，\n *   只保证逻辑与 interval_cover.py 逐行等价（等价性由\n *   verify_interval_cover_c_mirror.py 把本文件转写成 Python 后对拍确认）。\n *   提交前请自行编译一次。\n *\n * 编译：gcc -O2 -o interval_cover.exe interval_cover.c\n * 运行：./interval_cover.exe < input.txt\n *\n * 输入：多组测试数据，每组 2 行\n *         第 1 行：n m    （1 <= n <= 1000，1 <= m <= 20）\n *         第 2 行：n 个互不相同的整数，单位区间的左端点\n * 输出：每组一行 —— 至多 m 条线段覆盖全部单位区间的最小总长度\n *\n * 算法：排序 + 贪心剪最大的空隙。详见 interval_cover.py 的文件头。\n *   答案 = span - (最大的 m-1 个 gap 之和)\n *   interval 口径：span = x[n-1] + 1 - x[0]，gap = x[i+1] - x[i] - 1\n *   point    口径：span = x[n-1] - x[0]，    gap = x[i+1] - x[i]\n *\n * 注意 long long：interval 口径下答案可以达到 2*10^9 + 1 量级（x 可取 +-10^6 以上），\n *   用 int 会溢出。全程用 long long。\n *\n * 输入解析：手写基于 getchar() 的读整数，**不用 strtoll**。\n *   strtoll 太宽松：会接受 \"0x1A\"（解成 0）、把 \"12abc\" 截断成 12（陷阱 13）。\n *   手写的版本遇到非数字就停、并且把多读的那个字符放回，能保证 token 被完整消费。\n *   它天然地自动跳过空格 / 换行 / CRLF / 空行，所以「n 与数组同行」「数字跨行」\n *   「图与图之间空行」这些形态都不用特判。\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n\n/* 判题口径开关：题面正文写「单位区间」，但它自己给的样例输出 3 只有 point 口径才对得上。\n * ★ 已实测确认 OJ 判 point 口径（那组样例要 3），故默认 0。\n *   0 = point   （默认，OJ 口径；样例得 3；m >= n 时答案为 0）\n *   1 = interval（题面正文字面口径；样例得 6，与样例输出不符，别用这个交）\n */\n#define MODEL_INTERVAL 0\n\n#define MAX_N 1000\n#define MAX_M 20\n\nstatic long long xs[MAX_N];\nstatic long long gaps[MAX_N];\n\n/* 读一个整数。返回 1 成功、0 遇到 EOF、-1 读到非法 token。 */\nstatic int read_int(long long *out)\n{\n    int c;\n    int neg = 0;\n    int got = 0;\n    long long v = 0;\n\n    /* 跳过所有空白（空格 / 制表 / 换行 / 回车 / 换页 / 垂直制表） */\n    do {\n        c = getchar();\n    } while (c == ' ' || c == '\\t' || c == '\\n' || c == '\\r' ||\n             c == '\\f' || c == '\\v');\n\n    if (c == EOF) {\n        return 0;\n    }\n    if (c == '-') {\n        neg = 1;\n        c = getchar();\n    } else if (c == '+') {\n        c = getchar();\n    }\n\n    while (c >= '0' && c <= '9') {\n        v = v * 10 + (c - '0');\n        got = 1;\n        c = getchar();\n    }\n\n    if (!got) {\n        /* 这个 token 不是数字（比如 \"abc\" 或 \"0x1A\" 里的 'x' 之后）。\n         * 不放回 c，让下一次调用继续从 c 往后读 —— 若调用方还想继续，\n         * 它会立刻再撞上一次失败，从而中止，不会把伪答案吐进 stdout。 */\n        return -1;\n    }\n    if (c != EOF) {\n        ungetc(c, stdin);        /* 多读了一个字符，放回去 */\n    }\n    *out = neg ? -v : v;\n    return 1;\n}\n\n/* 升序 */\nstatic int cmp_ll_asc(const void *a, const void *b)\n{\n    long long x = *(const long long *)a;\n    long long y = *(const long long *)b;\n    if (x < y) return -1;\n    if (x > y) return 1;\n    return 0;\n}\n\n/* 降序 */\nstatic int cmp_ll_desc(const void *a, const void *b)\n{\n    long long x = *(const long long *)a;\n    long long y = *(const long long *)b;\n    if (x > y) return -1;\n    if (x < y) return 1;\n    return 0;\n}\n\nint main(void)\n{\n    long long n_ll, m_ll;\n    int rc;\n\n    while ((rc = read_int(&n_ll)) == 1) {\n        int i;\n        int n, m, k;\n        long long span, cut;\n\n        /* 铁律 6：n 决定后面还要吃多少 token，越界必须中止，不能 continue ——\n         * 一旦 continue，后面的数字会被当成下一组的 n，把伪答案打进 stdout。 */\n        if (n_ll < 1 || n_ll > MAX_N) {\n            fprintf(stderr, \"[!] n 越界: %lld（应为 1 <= n <= %d）\\n\", n_ll, MAX_N);\n            return 0;\n        }\n\n        if (read_int(&m_ll) != 1) {\n            fprintf(stderr, \"[!] 数据不足：缺少 m\\n\");\n            return 0;\n        }\n\n        /* m 越界只警告不中止：m 不影响 token 流，中止会连累后面的组。 */\n        if (m_ll < 1 || m_ll > MAX_M) {\n            fprintf(stderr, \"[!] 提示：m=%lld 超出题面上限（1 <= m <= %d），\"\n                            \"仍按原值计算\\n\", m_ll, MAX_M);\n        }\n\n        n = (int)n_ll;\n        m = (int)m_ll;\n\n        for (i = 0; i < n; i++) {\n            long long v;\n            if (read_int(&v) != 1) {\n                fprintf(stderr, \"[!] 数据不足：声明 n=%d，实际只读到 %d 个\\n\", n, i);\n                return 0;\n            }\n            xs[i] = v;\n        }\n\n        qsort(xs, (size_t)n, sizeof(long long), cmp_ll_asc);\n\n#if MODEL_INTERVAL\n        span = xs[n - 1] + 1 - xs[0];\n        for (i = 0; i < n - 1; i++) {\n            gaps[i] = xs[i + 1] - xs[i] - 1;\n        }\n#else\n        span = xs[n - 1] - xs[0];\n        for (i = 0; i < n - 1; i++) {\n            gaps[i] = xs[i + 1] - xs[i];\n        }\n#endif\n\n        if (n > 1) {\n            qsort(gaps, (size_t)(n - 1), sizeof(long long), cmp_ll_desc);\n        }\n\n        k = m - 1;                       /* 最多剪 m-1 刀 */\n        if (k > n - 1) {                 /* 只有 n-1 个位置可剪 */\n            k = n - 1;\n        }\n        if (k < 0) {\n            k = 0;\n        }\n\n        cut = 0;\n        for (i = 0; i < k; i++) {\n            cut += gaps[i];\n        }\n\n        printf(\"%lld\\n\", span - cut);\n        fflush(stdout);\n    }\n\n    if (rc == -1) {\n        fprintf(stderr, \"[!] 非法输入（读到了不是整数的 token）\\n\");\n        return 0;\n    }\n    return 0;\n}\n"}, {"label": "验证脚本 verify_interval_cover.py", "file": "verify_interval_cover.py", "lang": "py", "stripped": "import ast\nimport importlib.util\nimport io\nimport os\nimport random\nimport re\nimport subprocess\nimport sys\nimport time\nfrom itertools import combinations\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nMINI = os.path.join(HERE, \"interval_cover.py\")\nDETAILED = os.path.join(HERE, \"interval_cover_detailed.py\")\nPY = sys.executable\n\nFAILS = []\n\ndef check(cond, msg):\n    if cond:\n        print(\"  . \" + msg)\n    else:\n        print(\"  X \" + msg)\n        FAILS.append(msg)\n    return cond\n\ndef load_module(path, name):\n    spec = importlib.util.spec_from_file_location(name, path)\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\ndef seg_cost(xs, l, r, model):\n    if model == \"point\":\n        return xs[r] - xs[l]\n    return xs[r] + 1 - xs[l]\n\ndef brute_enumerate(x, m, model):\n    xs = sorted(x)\n    n = len(xs)\n    best = None\n    for g in range(1, min(m, n) + 1):\n        for cuts in combinations(range(1, n), g - 1):\n            b = (0,) + cuts + (n,)\n            total = 0\n            for t in range(g):\n                total += seg_cost(xs, b[t], b[t + 1] - 1, model)\n            if best is None or total < best:\n                best = total\n    return best\n\ndef dp_solve(x, m, model):\n    xs = sorted(x)\n    n = len(xs)\n    INF = float(\"inf\")\n    f = [[INF] * (m + 1) for _ in range(n + 1)]\n    f[0][0] = 0\n    for k in range(1, m + 1):\n        for j in range(1, n + 1):\n            row = f[j]\n            for i in range(k - 1, j):\n                v = f[i][k - 1]\n                if v == INF:\n                    continue\n                c = v + seg_cost(xs, i, j - 1, model)\n                if c < row[k]:\n                    row[k] = c\n    return min(f[n][k] for k in range(1, m + 1))\n\ndef dp_plan(x, m, model):\n    xs = sorted(x)\n    n = len(xs)\n    INF = float(\"inf\")\n    f = [[INF] * (m + 1) for _ in range(n + 1)]\n    ch = [[-1] * (m + 1) for _ in range(n + 1)]\n    f[0][0] = 0\n    for k in range(1, m + 1):\n        for j in range(1, n + 1):\n            for i in range(k - 1, j):\n                v = f[i][k - 1]\n                if v == INF:\n                    continue\n                c = v + seg_cost(xs, i, j - 1, model)\n                if c < f[j][k]:\n                    f[j][k] = c\n                    ch[j][k] = i\n\n    best, best_k = INF, -1\n    for k in range(1, m + 1):\n        if f[n][k] < best:\n            best, best_k = f[n][k], k\n\n    plan = []\n    j, k = n, best_k\n    while k > 0:\n        i = ch[j][k]\n        plan.append((i, j - 1))\n        j, k = i, k - 1\n    plan.reverse()\n    return best, plan\n\ndef plan_total(xs, plan, model):\n    return sum(seg_cost(xs, l, r, model) for (l, r) in plan)\n\ndef test_brute(mini, rng):\n    print(\"[1] mini == 暴力枚举所有分组\")\n    bad = 0\n    total = 0\n    for model in (\"interval\", \"point\"):\n        for _ in range(3000):\n            n = rng.randint(1, 9)\n            m = rng.randint(1, 6)\n            pool = list(range(-12, 13))\n            x = rng.sample(pool, n)\n            got = mini.min_length(list(x), m, model)\n            exp = brute_enumerate(x, m, model)\n            total += 1\n            if got != exp:\n                bad += 1\n                if bad <= 3:\n                    print(\"      MISMATCH model=%s n=%d m=%d x=%s got=%s exp=%s\"\n                          % (model, n, m, sorted(x), got, exp))\n    check(bad == 0, \"对拍 %d 组（含 interval / point 两种口径），不符 %d 组\" % (total, bad))\n\ndef test_dp(mini, rng):\n    print(\"[2] mini == 区间 DP（思路完全不同的独立实现）\")\n    bad = 0\n    total = 0\n    for model in (\"interval\", \"point\"):\n        for _ in range(400):\n            n = rng.randint(1, 60)\n            m = rng.randint(1, 8)\n            lo = rng.choice([-1000000, -50, 0, 1000])\n            span = rng.choice([80, 1000, 100000])\n            pool = rng.sample(range(lo, lo + span), min(n, span))\n            x = pool\n            got = mini.min_length(list(x), m, model)\n            exp = dp_solve(x, m, model)\n            total += 1\n            if got != exp:\n                bad += 1\n                if bad <= 3:\n                    print(\"      MISMATCH model=%s n=%d m=%d got=%s exp=%s\"\n                          % (model, n, m, got, exp))\n    check(bad == 0, \"对拍 %d 组，不符 %d 组\" % (total, bad))\n\ndef test_plan_legal(mini, rng):\n    print(\"[3] 方案可执行性（把线段真摆出来，逐条核）\")\n    bad = 0\n    total = 0\n    for model in (\"interval\", \"point\"):\n        for _ in range(800):\n            n = rng.randint(1, 30)\n            m = rng.randint(1, 7)\n            x = rng.sample(range(-60, 61), n)\n            xs = sorted(x)\n            got = mini.min_length(list(x), m, model)\n            best, plan = dp_plan(x, m, model)\n            total += 1\n\n            problems = []\n\n            if plan_total(xs, plan, model) != got:\n                problems.append(\"总长 %d != 答案 %d\" % (plan_total(xs, plan, model), got))\n\n            if len(plan) > m:\n                problems.append(\"段数 %d > m=%d\" % (len(plan), m))\n\n            cover = [0] * n\n            for (l, r) in plan:\n                for i in range(l, r + 1):\n                    cover[i] += 1\n            if cover != [1] * n:\n                problems.append(\"覆盖计数=%s\" % cover)\n\n            for (l, r) in plan:\n                left, right = xs[l], xs[r] + 1\n                for i in range(l, r + 1):\n                    if not (left <= xs[i] and xs[i] + 1 <= right):\n                        problems.append(\"线段 [%d,%d] 盖不住 [%d,%d]\"\n                                        % (left, right, xs[i], xs[i] + 1))\n                        break\n\n            if problems:\n                bad += 1\n                if bad <= 3:\n                    print(\"      BAD model=%s n=%d m=%d x=%s : %s\"\n                          % (model, n, m, xs, \"; \".join(problems)))\n    check(bad == 0, \"实跑 %d 组，非法方案 %d 组\" % (total, bad))\n\ndef test_bounds(mini, rng):\n    print(\"[4] 下界 / 上界 / 规模\")\n    bad = 0\n\n    for _ in range(400):\n        n = rng.randint(1, 40)\n        m = rng.randint(1, 6)\n        x = rng.sample(range(-200, 200), n)\n        got = mini.min_length(list(x), m, \"interval\")\n        if got < n:\n            bad += 1\n            if bad <= 3:\n                print(\"      破下界: n=%d m=%d got=%d\" % (n, m, got))\n    check(bad == 0, \"interval 口径下答案恒 >= n（400 组）\")\n\n    bad = 0\n    for _ in range(400):\n        n = rng.randint(1, 50)\n        m = rng.randint(1, 8)\n        x = sorted(rng.sample(range(-100, 100), n))\n        got = mini.min_length(list(x), m, \"interval\")\n        g = min(m, n)\n        cuts = [round(n * t / g) for t in range(1, g)]\n        b = [0] + cuts + [n]\n        view = 0\n        for t in range(len(b) - 1):\n            l, r = b[t], b[t + 1] - 1\n            if r >= l:\n                view += seg_cost(x, l, r, \"interval\")\n        if got > view:\n            bad += 1\n            if bad <= 3:\n                print(\"      超过可行解: n=%d m=%d got=%d 可行解=%d\" % (n, m, got, view))\n    check(bad == 0, \"答案恒 <= 任意可行分组解（400 组）\")\n\n    bad = 0\n    big_ok = 0\n    for _ in range(6):\n        n = 1000\n        m = rng.randint(1, 20)\n        x = rng.sample(range(-500000, 500000), n)\n        got = mini.min_length(list(x), m, \"interval\")\n        if got < n:\n            bad += 1\n        else:\n            big_ok += 1\n    check(bad == 0, \"n=1000 六组跑通且守住下界（%d/6）\" % big_ok)\n\nANCHORS = [\n\n    ([1, 2, 4, 5, -2, 6], 3, \"interval\", 6, \"题面样例；interval 口径得 6\"),\n    ([1, 2, 4, 5, -2, 6], 3, \"point\", 3, \"题面样例的官方输出 3（只有 point 口径吻合）\"),\n    ([1, 2, 4, 5, -2, 6], 1, \"interval\", 9, \"m=1 不给剪：span = (6+1)-(-2)\"),\n    ([1, 2, 4, 5, -2, 6], 1, \"point\", 8, \"m=1 不给剪：span = 6-(-2)\"),\n\n    ([1, 2, 3], 1, \"interval\", 3, \"三个区间接壤成 [1,4]\"),\n    ([1, 2, 3], 2, \"interval\", 3, \"★钉子：接壤处 gap=0，剪了不省；\"\n                                 \"gap 忘了 -1 的错法会得 2\"),\n    ([1, 2, 3], 5, \"interval\", 3, \"m>=n：每个区间一条长 1 的线段\"),\n    ([1, 2, 3], 2, \"point\", 1, \"point 口径剪 1 个 gap=1\"),\n    ([1, 2, 3], 3, \"point\", 0, \"m>=n，point 口径答案为 0\"),\n\n    ([7], 1, \"interval\", 1, \"n=1：一条长度 1 的线段\"),\n    ([-7], 1, \"interval\", 1, \"n=1 负坐标\"),\n    ([7], 1, \"point\", 0, \"n=1，point 口径：退化为点\"),\n    ([7], 20, \"interval\", 1, \"n=1 且 m 很大\"),\n\n    ([1, 2, 10, 11], 2, \"interval\", 4, \"★钉子：必须剪**最大**的空隙 7，\"\n                                       \"剪错地方会得 11\"),\n    ([1, 2, 10, 11], 3, \"interval\", 4, \"多给线段也只能剪到 n-1 刀\"),\n    ([-5, 5], 1, \"interval\", 11, \"负坐标：span = 6-(-5)\"),\n    ([-5, 5], 2, \"interval\", 2, \"两条线各长 1\"),\n    ([-5, 5], 1, \"point\", 10, \"point 口径 span = 10\"),\n    ([0, 1, 2, 3], 1, \"interval\", 4, \"从 0 起，接壤链\"),\n    ([0, 1, 2, 3], 2, \"interval\", 4, \"全长只有 4，剪哪儿都一样\"),\n\n    ([-1000000, 1000000], 1, \"interval\", 2000001, \"大数：span = 1000001+1000000\"),\n    ([-1000000, 1000000], 2, \"interval\", 2, \"大数 + m>=n\"),\n    ([-1000000, 1000000], 2, \"point\", 0, \"大数 + point + m>=n\"),\n]\n\ndef test_anchors(mini):\n    print(\"[5] 锚定用例\")\n    bad = 0\n    for (x, m, model, exp, why) in ANCHORS:\n        got = mini.min_length(list(x), m, model)\n        if got != exp:\n            bad += 1\n            print(\"      X x=%s m=%d model=%s 期望 %d 实得 %d  (%s)\"\n                  % (sorted(x), m, model, exp, got, why))\n    check(bad == 0, \"%d 条锚定全过\" % len(ANCHORS))\n\ndef run_mini(stdin_text):\n    p = subprocess.run([PY, MINI], input=stdin_text.encode(\"utf-8\"),\n                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n    out = p.stdout.decode(\"utf-8\").replace(\"\\r\\n\", \"\\n\")\n    err = p.stderr.decode(\"utf-8\").replace(\"\\r\\n\", \"\\n\")\n    return p.returncode, out, err\n\ndef test_subprocess(mini):\n    print(\"[6] 端到端 subprocess（模拟 OJ）\")\n\n    legal = [\n\n        (\"6 3\\n1 2 4 5 -2 6\\n\",                        \"6\\n\",      \"3\\n\",     \"题面样例\"),\n        (\"6 3\\n1 2 4 5 -2 6\",                          \"6\\n\",      \"3\\n\",     \"末尾没有换行\"),\n        (\"6 3\\r\\n1 2 4 5 -2 6\\r\\n\",                    \"6\\n\",      \"3\\n\",     \"CRLF\"),\n        (\"6 3\\n\\n1 2 4 5 -2 6\\n\\n\",                    \"6\\n\",      \"3\\n\",     \"夹空行\"),\n        (\"6 3 1 2 4 5 -2 6\\n\",                         \"6\\n\",      \"3\\n\",     \"n m 和 x 全挤一行\"),\n        (\"  6   3  \\n 1 2 4 5 -2 6 \\n\",                \"6\\n\",      \"3\\n\",     \"多余空白\"),\n        (\"1 1\\n7\\n\",                                   \"1\\n\",      \"0\\n\",     \"n=1\"),\n        (\"3 5\\n1 2 3\\n\",                               \"3\\n\",      \"0\\n\",     \"m>n\"),\n        (\"3 20\\n1 2 3\\n\",                              \"3\\n\",      \"0\\n\",     \"m 取上限 20\"),\n        (\"6 3\\n1 2 4 5 -2 6\\n3 1\\n1 2 3\\n\",            \"6\\n3\\n\",   \"3\\n2\\n\",  \"多组（EOF 结束）\"),\n        (\"6 3\\n1 2 4 5 -2 6\\n\\n\\n4 2\\n1 2 10 11\\n\",    \"6\\n4\\n\",   \"3\\n2\\n\",  \"多组 + 空行\"),\n        (\"2 1\\n-1000000 1000000\\n\",                    \"2000001\\n\", \"2000000\\n\", \"大数\"),\n        (\"3 2\\n1 2 3\\n3 2\\n1 2 3\\n3 2\\n1 2 3\\n\",       \"3\\n3\\n3\\n\", \"1\\n1\\n1\\n\", \"同一组连来三次\"),\n        (\"1 1\\n-7\\n2 2\\n-5 5\\n\",                       \"1\\n2\\n\",   \"0\\n0\\n\",  \"n=1 与 n=2 混排\"),\n        (\"5 2\\n0 1 2 100 101\\n\",                       \"5\\n\",      \"3\\n\",     \"两块：剪 [2,100] 的 gap=97\"),\n    ]\n    bad = 0\n    col = 1 if mini.MODEL == \"point\" else 0\n    for i, row in enumerate(legal):\n        inp, exp, why = row[0], row[1 + col], row[3]\n        rc, out, err = run_mini(inp)\n        if out != exp or rc != 0:\n            bad += 1\n            print(\"      X 合法用例 %d (%s): rc=%s out=%r 期望 %r err=%r\"\n                  % (i + 1, why, rc, out, exp, err))\n    check(bad == 0, \"合法 IO %d/%d（按当前 MODEL=%s 口径核对）\"\n          % (len(legal) - bad, len(legal), mini.MODEL))\n\n    illegal = [\n        (\"\", \"\", \"空输入\"),\n        (\"0 3\\n1 2 3\\n\", \"\", \"n=0 越界（不是哨兵，题面 n>=1）\"),\n        (\"1001 3\\n\" + \" \".join(str(i) for i in range(1001)) + \"\\n\", \"\", \"n 越界 1001\"),\n        (\"-3 2\\n1 2 3\\n\", \"\", \"n 为负\"),\n        (\"abc 2\\n1 2 3\\n\", \"\", \"n 不是整数\"),\n        (\"3\\n1 2 3\\n\", \"\", \"只有 n 没有 m\"),\n        (\"5 2\\n1 2 3\\n\", \"\", \"声明 n=5 只给 3 个 x\"),\n        (\"5 2\\n1 2 3\\n\", \"\", \"数据不足（同上，重复确认）\"),\n    ]\n    bad = 0\n    for i, (inp, exp, why) in enumerate(illegal):\n        rc, out, err = run_mini(inp)\n        ok = (out == exp)\n        if ok and inp.strip() and \"[!]\" not in err:\n\n            ok = False\n        if not ok:\n            bad += 1\n            print(\"      X 非法用例 %d (%s): out=%r 期望 %r err=%r\"\n                  % (i + 1, why, out, exp, err))\n    check(bad == 0, \"非法 IO %d/%d（stdout 干净 + stderr 有 [!]）\" % (len(illegal) - bad, len(illegal)))\n\ndef test_detailed(mini):\n    print(\"[7] 详细版：自校全绿且答案与极简版一致\")\n    cases = [\n        \"6 3\\n1 2 4 5 -2 6\\n\",\n        \"6 1\\n1 2 4 5 -2 6\\n\",\n        \"1 1\\n7\\n\",\n        \"3 2\\n1 2 3\\n\",\n        \"4 2\\n1 2 10 11\\n\",\n        \"2 1\\n-5 5\\n\",\n        \"6 3\\n1 2 4 5 -2 6\\n3 5\\n1 2 3\\n\",\n    ]\n    bad = 0\n    for i, inp in enumerate(cases):\n        p = subprocess.run([PY, DETAILED], input=inp.encode(\"utf-8\"),\n                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n        out = p.stdout.decode(\"utf-8\").replace(\"\\r\\n\", \"\\n\")\n        err = p.stderr.decode(\"utf-8\").replace(\"\\r\\n\", \"\\n\")\n        if \"***\" in out or \"自校未通过\" in err:\n            bad += 1\n            print(\"      X 详细版用例 %d 自校不过: %s\" % (i + 1, err.strip()))\n            continue\n\n        answers = [int(v) for v in re.findall(r\"^\\s*答案 = (-?\\d+)\", out, re.M)]\n        if not answers:\n            bad += 1\n            print(\"      X 详细版用例 %d 没找到答案行\" % (i + 1))\n            continue\n\n        rc, minout, _ = run_mini(inp)\n        exp = [int(v) for v in minout.split()]\n        if answers != exp:\n            bad += 1\n            print(\"      X 详细版用例 %d 答案 %s != 极简版 %s\" % (i + 1, answers, exp))\n    check(bad == 0, \"详细版 %d 个用例自校全绿且与极简版一致\" % len(cases))\n\ndef ast_check(path):\n    src = open(path, encoding=\"utf-8\").read()\n    tree = ast.parse(src)\n    bad = []\n    for node in ast.walk(tree):\n        if isinstance(node, ast.JoinedStr):\n            bad.append((\"f-string\", node.lineno))\n        elif isinstance(node, ast.NamedExpr):\n            bad.append((\"海象运算符\", node.lineno))\n        elif isinstance(node, ast.Nonlocal):\n            bad.append((\"nonlocal\", node.lineno))\n        elif isinstance(node, ast.AnnAssign):\n            bad.append((\"变量注解\", node.lineno))\n        elif isinstance(node, ast.FunctionDef):\n            if node.returns is not None:\n                bad.append((\"返回注解\", node.lineno))\n            for a in node.args.args:\n                if a.annotation is not None:\n                    bad.append((\"参数注解\", node.lineno))\n        elif isinstance(node, ast.Attribute):\n            if node.attr == \"buffer\":\n                bad.append((\"sys.stdin.buffer\", node.lineno))\n            elif node.attr == \"read\":\n\n                v = node.value\n                if isinstance(v, ast.Attribute) and v.attr == \"stdin\":\n                    bad.append((\"sys.stdin.read()\", node.lineno))\n        elif isinstance(node, ast.Call):\n            f = node.func\n            if isinstance(f, ast.Name) and f.id == \"input\":\n                bad.append((\"input()\", node.lineno))\n    return bad\n\ndef gbk_check(path):\n    src = open(path, encoding=\"utf-8\").read()\n    tree = ast.parse(src)\n    bad = []\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Constant) and isinstance(node.value, str):\n            try:\n                node.value.encode(\"gbk\")\n            except UnicodeEncodeError as e:\n                bad.append((node.lineno, str(e)))\n    return bad\n\ndef test_static():\n    print(\"[8] AST / GBK 静态检查\")\n    for path in (MINI, DETAILED):\n        name = os.path.basename(path)\n        bad = ast_check(path)\n        check(not bad, \"%s 无 Python3 独有语法 / input()（%s）\"\n              % (name, \"clean\" if not bad else bad))\n        bad2 = gbk_check(path)\n        check(not bad2, \"%s 字符串字面量 GBK 安全（%s）\"\n              % (name, \"clean\" if not bad2 else bad2))\n\ndef make_tokens(n_tokens):\n    toks = []\n    need = (n_tokens - 1) // 1002 + 1\n    for g in range(need):\n        toks.append(\"1000\")\n        toks.append(\"7\")\n        for i in range(1000):\n            toks.append(str(i * 2 + (g % 3)))\n    return \" \".join(toks[:n_tokens]) + \"\\n\"\n\ndef drain_with(mod_reader_factory, data):\n    old = sys.stdin\n    sys.stdin = io.StringIO(data)\n    try:\n        nxt = mod_reader_factory()\n        cnt = 0\n        while nxt() is not None:\n            cnt += 1\n    finally:\n        sys.stdin = old\n    return cnt\n\ndef bad_reader_factory():\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:\n                return None\n            buf.extend(line.split())\n        return buf.pop(0)\n    return nxt\n\ndef timed(mod_reader_factory, data, repeat=3):\n    best = None\n    for _ in range(repeat):\n        t0 = time.perf_counter()\n        drain_with(mod_reader_factory, data)\n        dt = time.perf_counter() - t0\n        if best is None or dt < best:\n            best = dt\n    return best\n\ndef test_reader(mini):\n    print(\"[9] 读取器斜率压测（线性约 4，O(k^2) 约 16）\")\n\n    K = 100000\n    data_k = make_tokens(K)\n    data_4k = make_tokens(4 * K)\n    drain_with(mini.make_reader, data_k)\n\n    t_k = timed(mini.make_reader, data_k, repeat=5)\n    t_4k = timed(mini.make_reader, data_4k, repeat=5)\n    slope = t_4k / t_k if t_k > 0 else float(\"inf\")\n    print(\"      mini.make_reader: K=%.4fs  4K=%.4fs  slope=%.2f\" % (t_k, t_4k, slope))\n    check(slope < 7.0, \"被测读取器斜率 %.2f < 7（不是 pop(0)）\" % slope)\n\n    Kb = 8000\n    b_data_k = make_tokens(Kb)\n    b_data_4k = make_tokens(4 * Kb)\n    b_k = timed(bad_reader_factory, b_data_k, repeat=2)\n    b_4k = timed(bad_reader_factory, b_data_4k, repeat=1)\n    bad_slope = b_4k / b_k if b_k > 0 else float(\"inf\")\n    print(\"      pop(0) 变体    : K=%.4fs  4K=%.4fs  slope=%.2f（K 取小值省时间）\"\n          % (b_k, b_4k, bad_slope))\n    check(bad_slope > 7.0, \"pop(0) 变体斜率 %.2f > 7（说明阈值有牙齿）\" % bad_slope)\n\ndef test_mutation_smoke(mini):\n    print(\"[10] 断言有牙齿（就地抽样变异）\")\n    src = open(MINI, encoding=\"utf-8\").read()\n\n    muts = [\n        (\"span 少 +1\", 'span = x[n - 1] + 1 - x[0]', 'span = x[n - 1] - x[0]'),\n        (\"gap 忘了 -1\", 'gaps = [x[i + 1] - x[i] - 1 for i in range(n - 1)]',\n         'gaps = [x[i + 1] - x[i] for i in range(n - 1)]'),\n        (\"剪最小的空隙\", 'gaps.sort(reverse=True)', 'gaps.sort()'),\n        (\"多剪一刀\", 'k = m - 1                                     # 最多剪 m-1 刀',\n         'k = m'),\n    ]\n    for name, old, new in muts:\n        if old not in src:\n            check(False, \"变异 %s：找不到锚点（脚本与源码脱节了）\" % name)\n            continue\n        mutated = src.replace(old, new, 1)\n        tmp = os.path.join(HERE, \"_mut_tmp.py\")\n        with open(tmp, \"w\", encoding=\"utf-8\") as f:\n            f.write(mutated)\n        try:\n            m2 = load_module(tmp, \"mut_mod\")\n            caught = False\n\n            rng2 = random.Random(999)\n            for _ in range(200):\n                n = rng2.randint(1, 8)\n                m = rng2.randint(1, 5)\n                x = rng2.sample(range(-15, 16), n)\n                if m2.min_length(list(x), m, \"interval\") != \\\n                        brute_enumerate(x, m, \"interval\"):\n                    caught = True\n                    break\n            check(caught, \"变异「%s」被抓\" % name)\n        finally:\n            if os.path.exists(tmp):\n                os.remove(tmp)\n\ndef main():\n    print(\"=\" * 70)\n    print(\"单位区间覆盖 —— 自动对拍 / 验收\")\n    print(\"=\" * 70)\n\n    mini = load_module(MINI, \"interval_cover\")\n    rng = random.Random(20260929)\n\n    test_brute(mini, rng)\n    test_dp(mini, rng)\n    test_plan_legal(mini, rng)\n    test_bounds(mini, rng)\n    test_anchors(mini)\n    test_subprocess(mini)\n    test_detailed(mini)\n    test_static()\n    test_reader(mini)\n    test_mutation_smoke(mini)\n\n    print(\"=\" * 70)\n    if FAILS:\n        print(\"FAILED: %d 项没过\" % len(FAILS))\n        for f in FAILS:\n            print(\"   - \" + f)\n        return 1\n    print(\"OK: 全部通过（暴力枚举 / DP / 方案可执行 / 下界 / 锚定 / subprocess / \"\n          \"详细版 / AST / GBK / 读取器斜率 / 抽样变异）\")\n    return 0\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n", "original": "# -*- coding: utf-8 -*-\n#\n# 单位区间覆盖 —— 自动对拍 / 验收脚本\n# =====================================\n#\n# 跑法（本机 locale 是 GBK，重定向日志时务必带 PYTHONIOENCODING=utf-8）：\n#     cd E:/沈云付算法/单位区间覆盖\n#     PYTHONIOENCODING=utf-8 python verify_interval_cover.py\n#\n# 期望输出（数字是示例值，随机器浮动；断言阈值见各段说明）：\n#     OK: mini==brute 21000 exhaustive | mini==dp 1600 cases | dp 方案可执行 1600 |\n#         anchors 22/22 | 下界 >= n | n=1000 6 组 | AST clean | GBK clean |\n#         subprocess 合法 15 / 非法 8 | reader slope ~4（阈值 7；pop(0) 变体 16.x 必须超标）|\n#         detailed 自校全绿\n#\n# 关键设计（本仓库的几条血泪教训，别改坏）：\n#   1. **载入被测文件本体**，不在脚本里复制一份算法（陷阱 10）：\n#      复制副本会导致\"改了本体、副本不动，脚本照样打印 OK\"。\n#   2. 对拍要**两个独立实现**：枚举所有分组（小 n，暴力）+ 区间 DP（中等 n）。\n#      再加一条**语义级**验证：DP 回溯出一份真实的分组方案，\n#      逐条检查\"这 m 条线段真的把每个单位区间盖住了吗、总长是不是答案\"。\n#      只比数字不比方案，是抓不到\"公式对但方案摆不出来\"的（陷阱 9）。\n#   3. 读取器退化成 O(k^2) 这个坑**结构上看不见**（陷阱 25、30）：\n#      所以专门加一段\"斜率法\"压测 —— 同一段读取代码读 K 与 4K 个 token 的耗时之比，\n#      线性约 4、平方约 16。比值不随机器快慢变。\n#      **并且同时实测一个 pop(0) 的坏变体**，确认这个阈值真的能抓人（否则就是装饰性断言）。\n#   4. AST 查语法禁用项，**不用 grep**（grep 会被 docstring 里的 \"isatty\"、\"read\" 误命中）。\n\nimport ast\nimport importlib.util\nimport io\nimport os\nimport random\nimport re\nimport subprocess\nimport sys\nimport time\nfrom itertools import combinations\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nMINI = os.path.join(HERE, \"interval_cover.py\")\nDETAILED = os.path.join(HERE, \"interval_cover_detailed.py\")\nPY = sys.executable\n\nFAILS = []\n\n\ndef check(cond, msg):\n    if cond:\n        print(\"  . \" + msg)\n    else:\n        print(\"  X \" + msg)\n        FAILS.append(msg)\n    return cond\n\n\ndef load_module(path, name):\n    \"\"\"按路径载入模块本体（不是复制算法！）。\"\"\"\n    spec = importlib.util.spec_from_file_location(name, path)\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\n\n# =====================================================================\n# 独立实现 1：最暴力 —— 枚举所有\"切成 g 段连续组\"的方式\n# =====================================================================\n\ndef seg_cost(xs, l, r, model):\n    \"\"\"一条线段盖住排序后 x[l..r] 这些单位区间所需的最短长度。\"\"\"\n    if model == \"point\":\n        return xs[r] - xs[l]\n    return xs[r] + 1 - xs[l]\n\n\ndef brute_enumerate(x, m, model):\n    \"\"\"把 n 个区间切成 g 段（g = 1..min(m,n)），枚举所有切法，取最小总长。\n\n    这是\"照着题面写\"的暴力：完全不做任何贪心推理，纯枚举。\n    \"\"\"\n    xs = sorted(x)\n    n = len(xs)\n    best = None\n    for g in range(1, min(m, n) + 1):\n        for cuts in combinations(range(1, n), g - 1):\n            b = (0,) + cuts + (n,)\n            total = 0\n            for t in range(g):\n                total += seg_cost(xs, b[t], b[t + 1] - 1, model)\n            if best is None or total < best:\n                best = total\n    return best\n\n\n# =====================================================================\n# 独立实现 2：区间 DP（思路与贪心完全不同）\n# =====================================================================\n\ndef dp_solve(x, m, model):\n    \"\"\"f[j][k] = 覆盖前 j 个区间、恰好用 k 条线段的最小总长；答案取 k<=m 的最小值。\"\"\"\n    xs = sorted(x)\n    n = len(xs)\n    INF = float(\"inf\")\n    f = [[INF] * (m + 1) for _ in range(n + 1)]\n    f[0][0] = 0\n    for k in range(1, m + 1):\n        for j in range(1, n + 1):\n            row = f[j]\n            for i in range(k - 1, j):\n                v = f[i][k - 1]\n                if v == INF:\n                    continue\n                c = v + seg_cost(xs, i, j - 1, model)\n                if c < row[k]:\n                    row[k] = c\n    return min(f[n][k] for k in range(1, m + 1))\n\n\ndef dp_plan(x, m, model):\n    \"\"\"DP + 回溯，返回 (最优值, 分组方案)。方案是**真实可执行的**分组，不是公式推的。\"\"\"\n    xs = sorted(x)\n    n = len(xs)\n    INF = float(\"inf\")\n    f = [[INF] * (m + 1) for _ in range(n + 1)]\n    ch = [[-1] * (m + 1) for _ in range(n + 1)]\n    f[0][0] = 0\n    for k in range(1, m + 1):\n        for j in range(1, n + 1):\n            for i in range(k - 1, j):\n                v = f[i][k - 1]\n                if v == INF:\n                    continue\n                c = v + seg_cost(xs, i, j - 1, model)\n                if c < f[j][k]:\n                    f[j][k] = c\n                    ch[j][k] = i\n\n    best, best_k = INF, -1\n    for k in range(1, m + 1):\n        if f[n][k] < best:\n            best, best_k = f[n][k], k\n\n    plan = []\n    j, k = n, best_k\n    while k > 0:\n        i = ch[j][k]\n        plan.append((i, j - 1))\n        j, k = i, k - 1\n    plan.reverse()\n    return best, plan\n\n\ndef plan_total(xs, plan, model):\n    return sum(seg_cost(xs, l, r, model) for (l, r) in plan)\n\n\n# =====================================================================\n# 1) 与暴力枚举对拍（小 n）\n# =====================================================================\n\ndef test_brute(mini, rng):\n    print(\"[1] mini == 暴力枚举所有分组\")\n    bad = 0\n    total = 0\n    for model in (\"interval\", \"point\"):\n        for _ in range(3000):\n            n = rng.randint(1, 9)\n            m = rng.randint(1, 6)\n            pool = list(range(-12, 13))\n            x = rng.sample(pool, n)\n            got = mini.min_length(list(x), m, model)\n            exp = brute_enumerate(x, m, model)\n            total += 1\n            if got != exp:\n                bad += 1\n                if bad <= 3:\n                    print(\"      MISMATCH model=%s n=%d m=%d x=%s got=%s exp=%s\"\n                          % (model, n, m, sorted(x), got, exp))\n    check(bad == 0, \"对拍 %d 组（含 interval / point 两种口径），不符 %d 组\" % (total, bad))\n\n\n# =====================================================================\n# 2) 与区间 DP 对拍（中等 n，含大坐标）\n# =====================================================================\n\ndef test_dp(mini, rng):\n    print(\"[2] mini == 区间 DP（思路完全不同的独立实现）\")\n    bad = 0\n    total = 0\n    for model in (\"interval\", \"point\"):\n        for _ in range(400):\n            n = rng.randint(1, 60)\n            m = rng.randint(1, 8)\n            lo = rng.choice([-1000000, -50, 0, 1000])\n            span = rng.choice([80, 1000, 100000])\n            pool = rng.sample(range(lo, lo + span), min(n, span))\n            x = pool\n            got = mini.min_length(list(x), m, model)\n            exp = dp_solve(x, m, model)\n            total += 1\n            if got != exp:\n                bad += 1\n                if bad <= 3:\n                    print(\"      MISMATCH model=%s n=%d m=%d got=%s exp=%s\"\n                          % (model, n, m, got, exp))\n    check(bad == 0, \"对拍 %d 组，不符 %d 组\" % (total, bad))\n\n\n# =====================================================================\n# 3) 语义验证：DP 回溯出的方案必须真的能盖住、且总长 == mini 的答案\n# =====================================================================\n\ndef test_plan_legal(mini, rng):\n    print(\"[3] 方案可执行性（把线段真摆出来，逐条核）\")\n    bad = 0\n    total = 0\n    for model in (\"interval\", \"point\"):\n        for _ in range(800):\n            n = rng.randint(1, 30)\n            m = rng.randint(1, 7)\n            x = rng.sample(range(-60, 61), n)\n            xs = sorted(x)\n            got = mini.min_length(list(x), m, model)\n            best, plan = dp_plan(x, m, model)\n            total += 1\n\n            problems = []\n            # a) 方案总长 == mini 的答案\n            if plan_total(xs, plan, model) != got:\n                problems.append(\"总长 %d != 答案 %d\" % (plan_total(xs, plan, model), got))\n            # b) 段数 <= m\n            if len(plan) > m:\n                problems.append(\"段数 %d > m=%d\" % (len(plan), m))\n            # c) 每个区间恰好被一条线段盖住（不许漏，也不许重复）\n            cover = [0] * n\n            for (l, r) in plan:\n                for i in range(l, r + 1):\n                    cover[i] += 1\n            if cover != [1] * n:\n                problems.append(\"覆盖计数=%s\" % cover)\n            # d) 每条线段确实完整包含组内每个单位区间 [x_i, x_i+1]\n            for (l, r) in plan:\n                left, right = xs[l], xs[r] + 1\n                for i in range(l, r + 1):\n                    if not (left <= xs[i] and xs[i] + 1 <= right):\n                        problems.append(\"线段 [%d,%d] 盖不住 [%d,%d]\"\n                                        % (left, right, xs[i], xs[i] + 1))\n                        break\n\n            if problems:\n                bad += 1\n                if bad <= 3:\n                    print(\"      BAD model=%s n=%d m=%d x=%s : %s\"\n                          % (model, n, m, xs, \"; \".join(problems)))\n    check(bad == 0, \"实跑 %d 组，非法方案 %d 组\" % (total, bad))\n\n\n# =====================================================================\n# 4) 下界与规模\n# =====================================================================\n\ndef test_bounds(mini, rng):\n    print(\"[4] 下界 / 上界 / 规模\")\n    bad = 0\n    # interval 口径：并集测度恒等于 n（左端点是整数且互不相同，区间只可能共享端点），\n    # 所以答案不可能小于 n。这是独立于贪心公式的一条硬下界。\n    for _ in range(400):\n        n = rng.randint(1, 40)\n        m = rng.randint(1, 6)\n        x = rng.sample(range(-200, 200), n)\n        got = mini.min_length(list(x), m, \"interval\")\n        if got < n:\n            bad += 1\n            if bad <= 3:\n                print(\"      破下界: n=%d m=%d got=%d\" % (n, m, got))\n    check(bad == 0, \"interval 口径下答案恒 >= n（400 组）\")\n\n    # 用\"均匀切成 m 段\"这个**可行解**当上界：mini 的答案不可能比任何可行解还大\n    bad = 0\n    for _ in range(400):\n        n = rng.randint(1, 50)\n        m = rng.randint(1, 8)\n        x = sorted(rng.sample(range(-100, 100), n))\n        got = mini.min_length(list(x), m, \"interval\")\n        g = min(m, n)\n        cuts = [round(n * t / g) for t in range(1, g)]\n        b = [0] + cuts + [n]\n        view = 0\n        for t in range(len(b) - 1):\n            l, r = b[t], b[t + 1] - 1\n            if r >= l:\n                view += seg_cost(x, l, r, \"interval\")\n        if got > view:\n            bad += 1\n            if bad <= 3:\n                print(\"      超过可行解: n=%d m=%d got=%d 可行解=%d\" % (n, m, got, view))\n    check(bad == 0, \"答案恒 <= 任意可行分组解（400 组）\")\n\n    # 大规模：n=1000（题面上限）\n    bad = 0\n    big_ok = 0\n    for _ in range(6):\n        n = 1000\n        m = rng.randint(1, 20)\n        x = rng.sample(range(-500000, 500000), n)\n        got = mini.min_length(list(x), m, \"interval\")\n        if got < n:\n            bad += 1\n        else:\n            big_ok += 1\n    check(bad == 0, \"n=1000 六组跑通且守住下界（%d/6）\" % big_ok)\n\n\n# =====================================================================\n# 5) 锚定用例（每条都钉死一种具体错法）\n# =====================================================================\n\nANCHORS = [\n    # (x, m, model, 期望, 说明)\n    ([1, 2, 4, 5, -2, 6], 3, \"interval\", 6, \"题面样例；interval 口径得 6\"),\n    ([1, 2, 4, 5, -2, 6], 3, \"point\", 3, \"题面样例的官方输出 3（只有 point 口径吻合）\"),\n    ([1, 2, 4, 5, -2, 6], 1, \"interval\", 9, \"m=1 不给剪：span = (6+1)-(-2)\"),\n    ([1, 2, 4, 5, -2, 6], 1, \"point\", 8, \"m=1 不给剪：span = 6-(-2)\"),\n\n    ([1, 2, 3], 1, \"interval\", 3, \"三个区间接壤成 [1,4]\"),\n    ([1, 2, 3], 2, \"interval\", 3, \"★钉子：接壤处 gap=0，剪了不省；\"\n                                 \"gap 忘了 -1 的错法会得 2\"),\n    ([1, 2, 3], 5, \"interval\", 3, \"m>=n：每个区间一条长 1 的线段\"),\n    ([1, 2, 3], 2, \"point\", 1, \"point 口径剪 1 个 gap=1\"),\n    ([1, 2, 3], 3, \"point\", 0, \"m>=n，point 口径答案为 0\"),\n\n    ([7], 1, \"interval\", 1, \"n=1：一条长度 1 的线段\"),\n    ([-7], 1, \"interval\", 1, \"n=1 负坐标\"),\n    ([7], 1, \"point\", 0, \"n=1，point 口径：退化为点\"),\n    ([7], 20, \"interval\", 1, \"n=1 且 m 很大\"),\n\n    ([1, 2, 10, 11], 2, \"interval\", 4, \"★钉子：必须剪**最大**的空隙 7，\"\n                                       \"剪错地方会得 11\"),\n    ([1, 2, 10, 11], 3, \"interval\", 4, \"多给线段也只能剪到 n-1 刀\"),\n    ([-5, 5], 1, \"interval\", 11, \"负坐标：span = 6-(-5)\"),\n    ([-5, 5], 2, \"interval\", 2, \"两条线各长 1\"),\n    ([-5, 5], 1, \"point\", 10, \"point 口径 span = 10\"),\n    ([0, 1, 2, 3], 1, \"interval\", 4, \"从 0 起，接壤链\"),\n    ([0, 1, 2, 3], 2, \"interval\", 4, \"全长只有 4，剪哪儿都一样\"),\n\n    # 大数（C 版要用 long long 的量级）\n    ([-1000000, 1000000], 1, \"interval\", 2000001, \"大数：span = 1000001+1000000\"),\n    ([-1000000, 1000000], 2, \"interval\", 2, \"大数 + m>=n\"),\n    ([-1000000, 1000000], 2, \"point\", 0, \"大数 + point + m>=n\"),\n]\n\n\ndef test_anchors(mini):\n    print(\"[5] 锚定用例\")\n    bad = 0\n    for (x, m, model, exp, why) in ANCHORS:\n        got = mini.min_length(list(x), m, model)\n        if got != exp:\n            bad += 1\n            print(\"      X x=%s m=%d model=%s 期望 %d 实得 %d  (%s)\"\n                  % (sorted(x), m, model, exp, got, why))\n    check(bad == 0, \"%d 条锚定全过\" % len(ANCHORS))\n\n\n# =====================================================================\n# 6) 端到端 subprocess（stdout 必须是纯答案，错误必须走 stderr）\n# =====================================================================\n\ndef run_mini(stdin_text):\n    p = subprocess.run([PY, MINI], input=stdin_text.encode(\"utf-8\"),\n                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n    out = p.stdout.decode(\"utf-8\").replace(\"\\r\\n\", \"\\n\")   # 陷阱 23：Windows 管道是 \\r\\n\n    err = p.stderr.decode(\"utf-8\").replace(\"\\r\\n\", \"\\n\")\n    return p.returncode, out, err\n\n\ndef test_subprocess(mini):\n    print(\"[6] 端到端 subprocess（模拟 OJ）\")\n\n    # 期望值随**判题口径**走，而不是写死在某一个口径上 ——\n    # 这样仓库默认口径改了（interval <-> point），这里跟着换一列就行，不会假报失败。\n    # 已实测确认 OJ 判 point（样例要 3），所以默认列是 point。\n    legal = [\n        #  输入                                         interval    point      说明\n        (\"6 3\\n1 2 4 5 -2 6\\n\",                        \"6\\n\",      \"3\\n\",     \"题面样例\"),\n        (\"6 3\\n1 2 4 5 -2 6\",                          \"6\\n\",      \"3\\n\",     \"末尾没有换行\"),\n        (\"6 3\\r\\n1 2 4 5 -2 6\\r\\n\",                    \"6\\n\",      \"3\\n\",     \"CRLF\"),\n        (\"6 3\\n\\n1 2 4 5 -2 6\\n\\n\",                    \"6\\n\",      \"3\\n\",     \"夹空行\"),\n        (\"6 3 1 2 4 5 -2 6\\n\",                         \"6\\n\",      \"3\\n\",     \"n m 和 x 全挤一行\"),\n        (\"  6   3  \\n 1 2 4 5 -2 6 \\n\",                \"6\\n\",      \"3\\n\",     \"多余空白\"),\n        (\"1 1\\n7\\n\",                                   \"1\\n\",      \"0\\n\",     \"n=1\"),\n        (\"3 5\\n1 2 3\\n\",                               \"3\\n\",      \"0\\n\",     \"m>n\"),\n        (\"3 20\\n1 2 3\\n\",                              \"3\\n\",      \"0\\n\",     \"m 取上限 20\"),\n        (\"6 3\\n1 2 4 5 -2 6\\n3 1\\n1 2 3\\n\",            \"6\\n3\\n\",   \"3\\n2\\n\",  \"多组（EOF 结束）\"),\n        (\"6 3\\n1 2 4 5 -2 6\\n\\n\\n4 2\\n1 2 10 11\\n\",    \"6\\n4\\n\",   \"3\\n2\\n\",  \"多组 + 空行\"),\n        (\"2 1\\n-1000000 1000000\\n\",                    \"2000001\\n\", \"2000000\\n\", \"大数\"),\n        (\"3 2\\n1 2 3\\n3 2\\n1 2 3\\n3 2\\n1 2 3\\n\",       \"3\\n3\\n3\\n\", \"1\\n1\\n1\\n\", \"同一组连来三次\"),\n        (\"1 1\\n-7\\n2 2\\n-5 5\\n\",                       \"1\\n2\\n\",   \"0\\n0\\n\",  \"n=1 与 n=2 混排\"),\n        (\"5 2\\n0 1 2 100 101\\n\",                       \"5\\n\",      \"3\\n\",     \"两块：剪 [2,100] 的 gap=97\"),\n    ]\n    bad = 0\n    col = 1 if mini.MODEL == \"point\" else 0        # 0 = interval 列，1 = point 列\n    for i, row in enumerate(legal):\n        inp, exp, why = row[0], row[1 + col], row[3]\n        rc, out, err = run_mini(inp)\n        if out != exp or rc != 0:\n            bad += 1\n            print(\"      X 合法用例 %d (%s): rc=%s out=%r 期望 %r err=%r\"\n                  % (i + 1, why, rc, out, exp, err))\n    check(bad == 0, \"合法 IO %d/%d（按当前 MODEL=%s 口径核对）\"\n          % (len(legal) - bad, len(legal), mini.MODEL))\n\n    illegal = [\n        (\"\", \"\", \"空输入\"),\n        (\"0 3\\n1 2 3\\n\", \"\", \"n=0 越界（不是哨兵，题面 n>=1）\"),\n        (\"1001 3\\n\" + \" \".join(str(i) for i in range(1001)) + \"\\n\", \"\", \"n 越界 1001\"),\n        (\"-3 2\\n1 2 3\\n\", \"\", \"n 为负\"),\n        (\"abc 2\\n1 2 3\\n\", \"\", \"n 不是整数\"),\n        (\"3\\n1 2 3\\n\", \"\", \"只有 n 没有 m\"),\n        (\"5 2\\n1 2 3\\n\", \"\", \"声明 n=5 只给 3 个 x\"),\n        (\"5 2\\n1 2 3\\n\", \"\", \"数据不足（同上，重复确认）\"),\n    ]\n    bad = 0\n    for i, (inp, exp, why) in enumerate(illegal):\n        rc, out, err = run_mini(inp)\n        ok = (out == exp)\n        if ok and inp.strip() and \"[!]\" not in err:\n            # 有输入却没报错，说明 silent 吞了\n            ok = False\n        if not ok:\n            bad += 1\n            print(\"      X 非法用例 %d (%s): out=%r 期望 %r err=%r\"\n                  % (i + 1, why, out, exp, err))\n    check(bad == 0, \"非法 IO %d/%d（stdout 干净 + stderr 有 [!]）\" % (len(illegal) - bad, len(illegal)))\n\n\n# =====================================================================\n# 7) 详细版自校\n# =====================================================================\n\ndef test_detailed(mini):\n    print(\"[7] 详细版：自校全绿且答案与极简版一致\")\n    cases = [\n        \"6 3\\n1 2 4 5 -2 6\\n\",\n        \"6 1\\n1 2 4 5 -2 6\\n\",\n        \"1 1\\n7\\n\",\n        \"3 2\\n1 2 3\\n\",\n        \"4 2\\n1 2 10 11\\n\",\n        \"2 1\\n-5 5\\n\",\n        \"6 3\\n1 2 4 5 -2 6\\n3 5\\n1 2 3\\n\",\n    ]\n    bad = 0\n    for i, inp in enumerate(cases):\n        p = subprocess.run([PY, DETAILED], input=inp.encode(\"utf-8\"),\n                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n        out = p.stdout.decode(\"utf-8\").replace(\"\\r\\n\", \"\\n\")\n        err = p.stderr.decode(\"utf-8\").replace(\"\\r\\n\", \"\\n\")\n        if \"***\" in out or \"自校未通过\" in err:\n            bad += 1\n            print(\"      X 详细版用例 %d 自校不过: %s\" % (i + 1, err.strip()))\n            continue\n        # 从详细版里抠出 \"答案 = N\"，与极简版对拍\n        answers = [int(v) for v in re.findall(r\"^\\s*答案 = (-?\\d+)\", out, re.M)]\n        if not answers:\n            bad += 1\n            print(\"      X 详细版用例 %d 没找到答案行\" % (i + 1))\n            continue\n        # 同一输入下的期望答案：用极简版真跑一遍\n        rc, minout, _ = run_mini(inp)\n        exp = [int(v) for v in minout.split()]\n        if answers != exp:\n            bad += 1\n            print(\"      X 详细版用例 %d 答案 %s != 极简版 %s\" % (i + 1, answers, exp))\n    check(bad == 0, \"详细版 %d 个用例自校全绿且与极简版一致\" % len(cases))\n\n\n# =====================================================================\n# 8) AST 静态检查（铁律 5：Python 3 独有语法会让老 OJ 直接 CE）\n# =====================================================================\n\ndef ast_check(path):\n    src = open(path, encoding=\"utf-8\").read()\n    tree = ast.parse(src)\n    bad = []\n    for node in ast.walk(tree):\n        if isinstance(node, ast.JoinedStr):\n            bad.append((\"f-string\", node.lineno))\n        elif isinstance(node, ast.NamedExpr):\n            bad.append((\"海象运算符\", node.lineno))\n        elif isinstance(node, ast.Nonlocal):\n            bad.append((\"nonlocal\", node.lineno))\n        elif isinstance(node, ast.AnnAssign):\n            bad.append((\"变量注解\", node.lineno))\n        elif isinstance(node, ast.FunctionDef):\n            if node.returns is not None:\n                bad.append((\"返回注解\", node.lineno))\n            for a in node.args.args:\n                if a.annotation is not None:\n                    bad.append((\"参数注解\", node.lineno))\n        elif isinstance(node, ast.Attribute):\n            if node.attr == \"buffer\":       # sys.stdin.buffer\n                bad.append((\"sys.stdin.buffer\", node.lineno))\n            elif node.attr == \"read\":\n                # sys.stdin.read() —— 铁律 1 禁用的写法（终端里像卡死）。\n                # 注意别误伤 readline：它的 attr 是 \"readline\"，不等于 \"read\"。\n                v = node.value\n                if isinstance(v, ast.Attribute) and v.attr == \"stdin\":\n                    bad.append((\"sys.stdin.read()\", node.lineno))\n        elif isinstance(node, ast.Call):\n            f = node.func\n            if isinstance(f, ast.Name) and f.id == \"input\":\n                bad.append((\"input()\", node.lineno))\n    return bad\n\n\ndef gbk_check(path):\n    \"\"\"所有字符串字面量必须能编成 GBK，否则重定向日志时会 UnicodeEncodeError（陷阱 31）。\"\"\"\n    src = open(path, encoding=\"utf-8\").read()\n    tree = ast.parse(src)\n    bad = []\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Constant) and isinstance(node.value, str):\n            try:\n                node.value.encode(\"gbk\")\n            except UnicodeEncodeError as e:\n                bad.append((node.lineno, str(e)))\n    return bad\n\n\ndef test_static():\n    print(\"[8] AST / GBK 静态检查\")\n    for path in (MINI, DETAILED):\n        name = os.path.basename(path)\n        bad = ast_check(path)\n        check(not bad, \"%s 无 Python3 独有语法 / input()（%s）\"\n              % (name, \"clean\" if not bad else bad))\n        bad2 = gbk_check(path)\n        check(not bad2, \"%s 字符串字面量 GBK 安全（%s）\"\n              % (name, \"clean\" if not bad2 else bad2))\n\n\n# =====================================================================\n# 9) 读取器斜率压测（陷阱 25 / 30）\n# =====================================================================\n\ndef make_tokens(n_tokens):\n    \"\"\"造一大坨合法 token，**全部塞在一行**（这才是能压出 pop(0) 退化的形态）。\"\"\"\n    toks = []\n    need = (n_tokens - 1) // 1002 + 1\n    for g in range(need):\n        toks.append(\"1000\")           # n\n        toks.append(\"7\")              # m\n        for i in range(1000):\n            toks.append(str(i * 2 + (g % 3)))   # 互不相同的整数\n    return \" \".join(toks[:n_tokens]) + \"\\n\"\n\n\ndef drain_with(mod_reader_factory, data):\n    old = sys.stdin\n    sys.stdin = io.StringIO(data)\n    try:\n        nxt = mod_reader_factory()\n        cnt = 0\n        while nxt() is not None:\n            cnt += 1\n    finally:\n        sys.stdin = old\n    return cnt\n\n\ndef bad_reader_factory():\n    \"\"\"故意写坏的读取器：正序入栈 + pop(0) —— 每次 memmove 整个缓冲，O(k^2)。\"\"\"\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:\n                return None\n            buf.extend(line.split())        # 正序\n        return buf.pop(0)                   # 每次都挪整个列表\n    return nxt\n\n\ndef timed(mod_reader_factory, data, repeat=3):\n    best = None\n    for _ in range(repeat):\n        t0 = time.perf_counter()\n        drain_with(mod_reader_factory, data)\n        dt = time.perf_counter() - t0\n        if best is None or dt < best:\n            best = dt           # 取最小值：抖动的噪声只会让耗时变大\n    return best\n\n\ndef test_reader(mini):\n    print(\"[9] 读取器斜率压测（线性约 4，O(k^2) 约 16）\")\n\n    # 规模要够大，否则单次测量只有 2 毫秒，调度抖动能把比值从 4 顶到 7 以上\n    # （本机实测过一次 7.29 的假警报，所以这里加到 10 万 token + 取 5 次最小值）。\n    K = 100000\n    data_k = make_tokens(K)\n    data_4k = make_tokens(4 * K)\n    drain_with(mini.make_reader, data_k)                 # warmup：先把首次的冷启动开销吃掉\n\n    t_k = timed(mini.make_reader, data_k, repeat=5)\n    t_4k = timed(mini.make_reader, data_4k, repeat=5)\n    slope = t_4k / t_k if t_k > 0 else float(\"inf\")\n    print(\"      mini.make_reader: K=%.4fs  4K=%.4fs  slope=%.2f\" % (t_k, t_4k, slope))\n    check(slope < 7.0, \"被测读取器斜率 %.2f < 7（不是 pop(0)）\" % slope)\n\n    # ★ 关键：确认这个阈值**真的能抓人**，否则就是装饰性断言（陷阱 20 / 30）。\n    #   同一段读取逻辑换成 pop(0) 的坏变体，斜率必须超标。\n    #   坏变体的规模故意取小：它是 O(k^2)，用 10 万 token 要跑几十秒。\n    Kb = 8000\n    b_data_k = make_tokens(Kb)\n    b_data_4k = make_tokens(4 * Kb)\n    b_k = timed(bad_reader_factory, b_data_k, repeat=2)\n    b_4k = timed(bad_reader_factory, b_data_4k, repeat=1)\n    bad_slope = b_4k / b_k if b_k > 0 else float(\"inf\")\n    print(\"      pop(0) 变体    : K=%.4fs  4K=%.4fs  slope=%.2f（K 取小值省时间）\"\n          % (b_k, b_4k, bad_slope))\n    check(bad_slope > 7.0, \"pop(0) 变体斜率 %.2f > 7（说明阈值有牙齿）\" % bad_slope)\n\n\n# =====================================================================\n# 10) 变异测试：把断言再验一遍是否是装饰品\n# =====================================================================\n\ndef test_mutation_smoke(mini):\n    \"\"\"就地做几个\"把代码改回错的\"的变异，确认本脚本会失败。\n\n    真正的全套变异测试在 verify_interval_cover_mutations.py；\n    这里只做两个抽样，保证本脚本的断言链不是摆设。\n    \"\"\"\n    print(\"[10] 断言有牙齿（就地抽样变异）\")\n    src = open(MINI, encoding=\"utf-8\").read()\n\n    muts = [\n        (\"span 少 +1\", 'span = x[n - 1] + 1 - x[0]', 'span = x[n - 1] - x[0]'),\n        (\"gap 忘了 -1\", 'gaps = [x[i + 1] - x[i] - 1 for i in range(n - 1)]',\n         'gaps = [x[i + 1] - x[i] for i in range(n - 1)]'),\n        (\"剪最小的空隙\", 'gaps.sort(reverse=True)', 'gaps.sort()'),\n        (\"多剪一刀\", 'k = m - 1                                     # 最多剪 m-1 刀',\n         'k = m'),\n    ]\n    for name, old, new in muts:\n        if old not in src:\n            check(False, \"变异 %s：找不到锚点（脚本与源码脱节了）\" % name)\n            continue\n        mutated = src.replace(old, new, 1)\n        tmp = os.path.join(HERE, \"_mut_tmp.py\")\n        with open(tmp, \"w\", encoding=\"utf-8\") as f:\n            f.write(mutated)\n        try:\n            m2 = load_module(tmp, \"mut_mod\")\n            caught = False\n            # 用一组小锚定直接判：变异后必然与暴力不符\n            # 注意：rng 必须建在循环**外面**，否则每次重播种、200 次都在测同一组数据，\n            # 一旦那组正好抓不到，就会假报\"没抓到\"（这个 bug 我自己先踩了一次）。\n            rng2 = random.Random(999)\n            for _ in range(200):\n                n = rng2.randint(1, 8)\n                m = rng2.randint(1, 5)\n                x = rng2.sample(range(-15, 16), n)\n                if m2.min_length(list(x), m, \"interval\") != \\\n                        brute_enumerate(x, m, \"interval\"):\n                    caught = True\n                    break\n            check(caught, \"变异「%s」被抓\" % name)\n        finally:\n            if os.path.exists(tmp):\n                os.remove(tmp)\n\n\n# =====================================================================\n\ndef main():\n    print(\"=\" * 70)\n    print(\"单位区间覆盖 —— 自动对拍 / 验收\")\n    print(\"=\" * 70)\n\n    mini = load_module(MINI, \"interval_cover\")\n    rng = random.Random(20260929)\n\n    test_brute(mini, rng)\n    test_dp(mini, rng)\n    test_plan_legal(mini, rng)\n    test_bounds(mini, rng)\n    test_anchors(mini)\n    test_subprocess(mini)\n    test_detailed(mini)\n    test_static()\n    test_reader(mini)\n    test_mutation_smoke(mini)\n\n    print(\"=\" * 70)\n    if FAILS:\n        print(\"FAILED: %d 项没过\" % len(FAILS))\n        for f in FAILS:\n            print(\"   - \" + f)\n        return 1\n    print(\"OK: 全部通过（暴力枚举 / DP / 方案可执行 / 下界 / 锚定 / subprocess / \"\n          \"详细版 / AST / GBK / 读取器斜率 / 抽样变异）\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n"}, {"label": "验证脚本 verify_interval_cover_c_mirror.py", "file": "verify_interval_cover_c_mirror.py", "lang": "py", "stripped": "import importlib.util\nimport os\nimport random\nimport sys\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nMINI = os.path.join(HERE, \"interval_cover.py\")\nCSRC = os.path.join(HERE, \"interval_cover.c\")\n\nFAILS = []\n\ndef check(cond, msg):\n    if cond:\n        print(\"  . \" + msg)\n    else:\n        print(\"  X \" + msg)\n        FAILS.append(msg)\n    return cond\n\ndef load_module(path, name):\n    spec = importlib.util.spec_from_file_location(name, path)\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\nEOF = -1\n\nBLANK = (\" \", \"\\t\", \"\\n\", \"\\r\", \"\\f\", \"\\v\")\n\nclass CStdin(object):\n\n    def __init__(self, text):\n        self.s = text\n        self.i = 0\n\n    def getchar(self):\n        if self.i >= len(self.s):\n            return EOF\n        c = self.s[self.i]\n        self.i += 1\n        return c\n\n    def ungetc(self, c):\n        if c != EOF:\n            self.i -= 1\n\ndef c_read_int(s):\n\n    c = s.getchar()\n    while c in BLANK:\n        c = s.getchar()\n\n    if c == EOF:\n        return 0, None\n\n    neg = False\n    if c == \"-\":\n        neg = True\n        c = s.getchar()\n    elif c == \"+\":\n        c = s.getchar()\n\n    v = 0\n    got = False\n    while c != EOF and \"0\" <= c <= \"9\":\n        v = v * 10 + (ord(c) - 48)\n        got = True\n        c = s.getchar()\n\n    if not got:\n        return -1, None\n\n    if c != EOF:\n        s.ungetc(c)\n\n    return 1, (-v if neg else v)\n\ndef c_solve(text, model_interval=True):\n    s = CStdin(text)\n    out = []\n\n    while True:\n        rc, n = c_read_int(s)\n        if rc != 1:\n            break\n        if n < 1 or n > 1000:\n            return out, \"n 越界中止\"\n        rc, m = c_read_int(s)\n        if rc != 1:\n            return out, \"缺 m\"\n\n        xs = []\n        for i in range(n):\n            rc, v = c_read_int(s)\n            if rc != 1:\n                return out, \"数据不足\"\n            xs.append(v)\n\n        xs.sort()\n\n        if model_interval:\n            span = xs[n - 1] + 1 - xs[0]\n            gaps = [xs[i + 1] - xs[i] - 1 for i in range(n - 1)]\n        else:\n            span = xs[n - 1] - xs[0]\n            gaps = [xs[i + 1] - xs[i] for i in range(n - 1)]\n\n        gaps.sort(reverse=True)\n\n        k = m - 1\n        if k > n - 1:\n            k = n - 1\n        if k < 0:\n            k = 0\n\n        cut = 0\n        for i in range(k):\n            cut += gaps[i]\n\n        out.append(span - cut)\n\n    return out, (\"非法 token\" if rc == -1 else None)\n\ndef feed(mini, n, m, x, model):\n    return mini.min_length(list(x), m, model)\n\ndef test_anchors(mini):\n    print(\"[1] 锚定用例（转写版 vs 本体）\")\n    anchors = [\n        ([1, 2, 4, 5, -2, 6], 3, \"interval\", 6),\n        ([1, 2, 4, 5, -2, 6], 3, \"point\", 3),\n        ([1, 2, 4, 5, -2, 6], 1, \"interval\", 9),\n        ([1, 2, 3], 2, \"interval\", 3),\n        ([1, 2, 3], 2, \"point\", 1),\n        ([1, 2, 3], 5, \"interval\", 3),\n        ([7], 1, \"interval\", 1),\n        ([-7], 1, \"interval\", 1),\n        ([1, 2, 10, 11], 2, \"interval\", 4),\n        ([-5, 5], 1, \"interval\", 11),\n        ([-5, 5], 2, \"interval\", 2),\n        ([-1000000, 1000000], 1, \"interval\", 2000001),\n        ([-1000000, 1000000], 2, \"interval\", 2),\n        ([0, 1, 2, 3], 1, \"interval\", 4),\n    ]\n    bad = 0\n    for (x, m, model, exp) in anchors:\n        mi = \"interval\" if model == \"interval\" else \"point\"\n        text = \"%d %d\\n%s\\n\" % (len(x), m, \" \".join(str(v) for v in x))\n        got, _ = c_solve(text, mi == \"interval\")\n        want = feed(mini, len(x), m, x, model)\n        if got != [want] or want != exp:\n            bad += 1\n            print(\"      X x=%s m=%d %s: 转写=%s 本体=%s 期望=%d\"\n                  % (sorted(x), m, model, got, [want], exp))\n    check(bad == 0, \"%d 条锚定全过（含 2*10^6 量级，验证 long long 位宽）\" % len(anchors))\n\ndef test_random(mini):\n    print(\"[2] 随机对拍（转写版 vs 本体）\")\n    rng = random.Random(31415)\n    bad = 0\n    total = 0\n    for model_interval in (True, False):\n        for _ in range(10000):\n            n = rng.randint(1, 12)\n            m = rng.randint(1, 20)\n            x = rng.sample(range(-40, 41), n)\n            text = \"%d %d\\n%s\\n\" % (n, m, \" \".join(str(v) for v in x))\n            got, _ = c_solve(text, model_interval)\n            want = feed(mini, n, m, x, \"interval\" if model_interval else \"point\")\n            total += 1\n            if got != [want]:\n                bad += 1\n                if bad <= 3:\n                    print(\"      X n=%d m=%d x=%s 转写=%s 本体=%s\"\n                          % (n, m, sorted(x), got, [want]))\n    check(bad == 0, \"对拍 %d 组（两种口径各 10000），不符 %d 组\" % (total, bad))\n\ndef test_weird_input(mini):\n    print(\"[3] 畸形输入形态（C 的手写读取器要能忍）\")\n    cases = [\n        (\"6 3\\n1 2 4 5 -2 6\\n\", [6], \"标准两行\"),\n        (\"6 3 1 2 4 5 -2 6\", [6], \"全挤一行、末尾无换行\"),\n        (\"6\\n3\\n1 2 4 5 -2 6\\n\", [6], \"n 与 m 分两行\"),\n        (\"6 3\\n1\\n2\\n4\\n5\\n-2\\n6\\n\", [6], \"每个 x 一行\"),\n        (\"6 3\\r\\n1 2 4 5 -2 6\\r\\n\", [6], \"CRLF\"),\n        (\"\\n\\n6 3\\n\\n1 2 4 5 -2 6\\n\\n\\n\", [6], \"夹空行\"),\n        (\"   6   3   \\n   1  2  4  5  -2  6   \\n\", [6], \"多余空白\"),\n        (\"+6 +3\\n+1 2 4 5 -2 6\\n\", [6], \"正号\"),\n        (\"6 3\\n1 2 4 5 -2 6\\n6 3\\n1 2 4 5 -2 6\\n\", [6, 6], \"多组连排\"),\n        (\"1 1\\n7\\n\", [1], \"n=1\"),\n        (\"3 20\\n1 2 3\\n\", [3], \"m 上限\"),\n        (\"5 2\\n0 1 2 100 101\\n\", [5], \"剪中间大空隙\"),\n    ]\n    bad = 0\n    for (text, exp, why) in cases:\n        got, _ = c_solve(text, True)\n        if got != exp:\n            bad += 1\n            print(\"      X %s: got=%s exp=%s\" % (why, got, exp))\n    check(bad == 0, \"%d 种形态全过\" % len(cases))\n\ndef test_bad_input(mini):\n    print(\"[4] 非法输入要中止、不许错答\")\n    cases = [\n        (\"0 3\\n1 2 3\\n\", \"n=0\"),\n        (\"1001 3\\n1 2 3\\n\", \"n=1001\"),\n        (\"-3 2\\n1 2 3\\n\", \"n 为负\"),\n        (\"abc 2\\n1 2 3\\n\", \"n 非整数\"),\n        (\"3\\n1 2 3\\n\", \"缺 m\"),\n        (\"5 2\\n1 2 3\\n\", \"数据不足\"),\n    ]\n    bad = 0\n    for (text, why) in cases:\n        got, reason = c_solve(text, True)\n        if got != [] or reason is None:\n            bad += 1\n            print(\"      X %s: out=%s reason=%s\" % (why, got, reason))\n    check(bad == 0, \"%d 种非法输入全部中止且 stdout 零输出\" % len(cases))\n\ndef test_scale(mini):\n    print(\"[5] 大规模 n=1000\")\n    rng = random.Random(2718)\n    bad = 0\n    for _ in range(4):\n        n = 1000\n        m = rng.randint(1, 20)\n        x = rng.sample(range(-500000, 500000), n)\n        text = \"%d %d\\n%s\\n\" % (n, m, \" \".join(str(v) for v in x))\n        got, _ = c_solve(text, True)\n        want = feed(mini, n, m, x, \"interval\")\n        if got != [want]:\n            bad += 1\n            print(\"      X n=1000 m=%d: 转写=%s 本体=%s\" % (m, got, [want]))\n    check(bad == 0, \"n=1000 四组一致\")\n\ndef strip_c_comments(src):\n    out = []\n    i = 0\n    n = len(src)\n    while i < n:\n        c = src[i]\n        if c == \"/\" and i + 1 < n and src[i + 1] == \"*\":\n            j = src.find(\"*/\", i + 2)\n            j = n if j < 0 else j + 2\n            for k in range(i, j):\n                out.append(\"\\n\" if src[k] == \"\\n\" else \" \")\n            i = j\n        elif c == \"/\" and i + 1 < n and src[i + 1] == \"/\":\n            j = src.find(\"\\n\", i)\n            j = n if j < 0 else j\n            for k in range(i, j):\n                out.append(\" \")\n            i = j\n        elif c == '\"':\n            j = i + 1\n            while j < n and src[j] != '\"':\n                if src[j] == \"\\\\\":\n                    j += 1\n                j += 1\n            j = min(j + 1, n)\n            out.append(src[i:j])\n            i = j\n        else:\n            out.append(c)\n            i += 1\n    return \"\".join(out)\n\ndef test_c_source_anchors():\n    print(\"[6] interval_cover.c 源码锚点（防止文件被改坏 / 关键点被删）\")\n\n    probe = ('int a; /*注释里的 strtoll 不该被发现*/\\n'\n             '// 行注释里的 qsort 也不该\\n'\n             'char *s = \"字符串里的 /* 不是注释\";\\n'\n             'long long b;\\n')\n    code_probe = strip_c_comments(probe)\n    check(\"strtoll\" not in code_probe and \"qsort\" not in code_probe\n          and \"long long\" in code_probe and \"long long b;\" in code_probe,\n          \"注释剥离器自检（注释里的词被剥掉、代码里的词留下）\")\n\n    src = open(CSRC, encoding=\"utf-8\").read()\n    code = strip_c_comments(src)\n    anchors = [\n        (\"long long\", \"答案用 64 位，防溢出\"),\n        ('printf(\"%lld\\\\n\"', \"输出走 long long 格式符\"),\n        (\"#define MODEL_INTERVAL 0\", \"判题口径开关默认 point（OJ 实测口径）\"),\n        (\"ungetc(c, stdin)\", \"读整数时把多读的字符放回\"),\n        (\"qsort(xs, (size_t)n, sizeof(long long), cmp_ll_asc)\", \"升序排 x\"),\n        (\"qsort(gaps, (size_t)(n - 1), sizeof(long long), cmp_ll_desc)\", \"降序排空隙\"),\n        (\"if (n_ll < 1 || n_ll > MAX_N)\", \"n 越界检查\"),\n        (\"return 0;\", \"越界时中止\"),\n        (\"fflush(stdout)\", \"每组立即刷出\"),\n    ]\n    forbidden = [\n        (\"strtoll\", \"陷阱 13：strtoll 解析太宽松\"),\n        (\"scanf(\\\"%d\\\"\", \"用 %d 装 long long 会溢出\"),\n        (\"gets(\", \"gets 已废弃且危险\"),\n    ]\n    bad = 0\n    for (needle, why) in anchors:\n        if needle not in code:\n            bad += 1\n            print(\"      X 缺少锚点: %s（%s）\" % (needle, why))\n    for (needle, why) in forbidden:\n        if needle in code:\n            bad += 1\n            print(\"      X 出现禁用写法: %s（%s）\" % (needle, why))\n    check(bad == 0, \"锚点 %d 条全在、禁用写法 %d 条全无（均已剥除注释）\"\n          % (len(anchors), len(forbidden)))\n\n    check(\"fprintf(stderr\" in code, \"错误走 stderr（不污染 stdout）\")\n\ndef main():\n    print(\"=\" * 70)\n    print(\"interval_cover.c 逐行转写核对\")\n    print(\"=\" * 70)\n    print(\"注：本机无 C 编译器，这里只核对**逻辑**，不核对语法 / 宏 / qsort 细节。\")\n\n    mini = load_module(MINI, \"interval_cover\")\n    test_anchors(mini)\n    test_random(mini)\n    test_weird_input(mini)\n    test_bad_input(mini)\n    test_scale(mini)\n    test_c_source_anchors()\n\n    print(\"=\" * 70)\n    if FAILS:\n        print(\"FAILED: %d 项没过\" % len(FAILS))\n        for f in FAILS:\n            print(\"   - \" + f)\n        return 1\n    print(\"OK: C 逐行转写 == interval_cover.py（锚定 / 随机 20000 组 / \"\n          \"畸形输入 12 种 / 非法输入 6 种 / n=1000）；interval_cover.c 源码锚点全在\")\n    return 0\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n", "original": "# -*- coding: utf-8 -*-\n#\n# interval_cover.c 逻辑核对（本机没有 C 编译器，只能这么验）\n# =========================================================\n#\n# 做法：把 interval_cover.c **逐行转写**成 Python（包括它那个手写的 getchar 读整数），\n#       然后拿转写版和 interval_cover.py 对拍。二者的输入输出必须完全一致。\n#\n# 这**不能**替代编译（语法错误、宏展开、qsort 比较函数的细节都测不到），\n# 但能抓住\"算法写错、边界写反、读取器逻辑不对\"这类真正的逻辑错误。\n#\n# 跑法：\n#     cd E:/沈云付算法/单位区间覆盖\n#     PYTHONIOENCODING=utf-8 python verify_interval_cover_c_mirror.py\n#\n# 期望：\n#     OK: C 逐行转写 == interval_cover.py（锚定 23 条 + 随机 20000 组 + 畸形输入形态 12 种 +\n#         n=1000 大规模）| interval_cover.c 锚点 11 条全在\n\nimport importlib.util\nimport os\nimport random\nimport sys\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nMINI = os.path.join(HERE, \"interval_cover.py\")\nCSRC = os.path.join(HERE, \"interval_cover.c\")\n\nFAILS = []\n\n\ndef check(cond, msg):\n    if cond:\n        print(\"  . \" + msg)\n    else:\n        print(\"  X \" + msg)\n        FAILS.append(msg)\n    return cond\n\n\ndef load_module(path, name):\n    spec = importlib.util.spec_from_file_location(name, path)\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\n\n# =====================================================================\n# 逐行转写 interval_cover.c\n# =====================================================================\n\nEOF = -1\n\n# C 里 do-while 跳过的空白集合\nBLANK = (\" \", \"\\t\", \"\\n\", \"\\r\", \"\\f\", \"\\v\")\n\n\nclass CStdin(object):\n    \"\"\"模拟 C 的 stdin：按**字符**读，支持 ungetc（放回一个字符）。\"\"\"\n\n    def __init__(self, text):\n        self.s = text\n        self.i = 0\n\n    def getchar(self):\n        if self.i >= len(self.s):\n            return EOF\n        c = self.s[self.i]\n        self.i += 1\n        return c\n\n    def ungetc(self, c):\n        if c != EOF:\n            self.i -= 1\n\n\ndef c_read_int(s):\n    \"\"\"逐行转写 C 的 static int read_int(long long *out)。\n\n    返回 (rc, value)：rc = 1 成功 / 0 遇 EOF / -1 读了非法 token。\n    \"\"\"\n    # do { c = getchar(); } while (c == ' ' || ...);\n    c = s.getchar()\n    while c in BLANK:\n        c = s.getchar()\n\n    if c == EOF:\n        return 0, None\n\n    neg = False\n    if c == \"-\":\n        neg = True\n        c = s.getchar()\n    elif c == \"+\":\n        c = s.getchar()\n\n    v = 0\n    got = False\n    while c != EOF and \"0\" <= c <= \"9\":\n        v = v * 10 + (ord(c) - 48)\n        got = True\n        c = s.getchar()\n\n    if not got:\n        return -1, None          # 非法 token；故意不放回，与 C 一致\n\n    if c != EOF:\n        s.ungetc(c)              # 多读了一个字符，放回去\n\n    return 1, (-v if neg else v)\n\n\ndef c_solve(text, model_interval=True):\n    \"\"\"逐行转写 C 的 main()。返回 (输出行列表, 结束原因)。\"\"\"\n    s = CStdin(text)\n    out = []\n\n    while True:\n        rc, n = c_read_int(s)\n        if rc != 1:\n            break\n        if n < 1 or n > 1000:\n            return out, \"n 越界中止\"\n        rc, m = c_read_int(s)\n        if rc != 1:\n            return out, \"缺 m\"\n        # m 越界：C 里只打 stderr 提示，不中止\n        xs = []\n        for i in range(n):\n            rc, v = c_read_int(s)\n            if rc != 1:\n                return out, \"数据不足\"\n            xs.append(v)\n\n        xs.sort()                                     # qsort(cmp_ll_asc)\n\n        if model_interval:                            # #if MODEL_INTERVAL\n            span = xs[n - 1] + 1 - xs[0]\n            gaps = [xs[i + 1] - xs[i] - 1 for i in range(n - 1)]\n        else:                                         # #else\n            span = xs[n - 1] - xs[0]\n            gaps = [xs[i + 1] - xs[i] for i in range(n - 1)]\n\n        gaps.sort(reverse=True)                       # qsort(cmp_ll_desc)\n\n        k = m - 1\n        if k > n - 1:\n            k = n - 1\n        if k < 0:\n            k = 0\n\n        cut = 0\n        for i in range(k):\n            cut += gaps[i]\n\n        out.append(span - cut)\n\n    return out, (\"非法 token\" if rc == -1 else None)\n\n\n# =====================================================================\n# 对拍\n# =====================================================================\n\ndef feed(mini, n, m, x, model):\n    return mini.min_length(list(x), m, model)\n\n\ndef test_anchors(mini):\n    print(\"[1] 锚定用例（转写版 vs 本体）\")\n    anchors = [\n        ([1, 2, 4, 5, -2, 6], 3, \"interval\", 6),\n        ([1, 2, 4, 5, -2, 6], 3, \"point\", 3),\n        ([1, 2, 4, 5, -2, 6], 1, \"interval\", 9),\n        ([1, 2, 3], 2, \"interval\", 3),\n        ([1, 2, 3], 2, \"point\", 1),\n        ([1, 2, 3], 5, \"interval\", 3),\n        ([7], 1, \"interval\", 1),\n        ([-7], 1, \"interval\", 1),\n        ([1, 2, 10, 11], 2, \"interval\", 4),\n        ([-5, 5], 1, \"interval\", 11),\n        ([-5, 5], 2, \"interval\", 2),\n        ([-1000000, 1000000], 1, \"interval\", 2000001),   # 需要 long long\n        ([-1000000, 1000000], 2, \"interval\", 2),\n        ([0, 1, 2, 3], 1, \"interval\", 4),\n    ]\n    bad = 0\n    for (x, m, model, exp) in anchors:\n        mi = \"interval\" if model == \"interval\" else \"point\"\n        text = \"%d %d\\n%s\\n\" % (len(x), m, \" \".join(str(v) for v in x))\n        got, _ = c_solve(text, mi == \"interval\")\n        want = feed(mini, len(x), m, x, model)\n        if got != [want] or want != exp:\n            bad += 1\n            print(\"      X x=%s m=%d %s: 转写=%s 本体=%s 期望=%d\"\n                  % (sorted(x), m, model, got, [want], exp))\n    check(bad == 0, \"%d 条锚定全过（含 2*10^6 量级，验证 long long 位宽）\" % len(anchors))\n\n\ndef test_random(mini):\n    print(\"[2] 随机对拍（转写版 vs 本体）\")\n    rng = random.Random(31415)\n    bad = 0\n    total = 0\n    for model_interval in (True, False):\n        for _ in range(10000):\n            n = rng.randint(1, 12)\n            m = rng.randint(1, 20)\n            x = rng.sample(range(-40, 41), n)\n            text = \"%d %d\\n%s\\n\" % (n, m, \" \".join(str(v) for v in x))\n            got, _ = c_solve(text, model_interval)\n            want = feed(mini, n, m, x, \"interval\" if model_interval else \"point\")\n            total += 1\n            if got != [want]:\n                bad += 1\n                if bad <= 3:\n                    print(\"      X n=%d m=%d x=%s 转写=%s 本体=%s\"\n                          % (n, m, sorted(x), got, [want]))\n    check(bad == 0, \"对拍 %d 组（两种口径各 10000），不符 %d 组\" % (total, bad))\n\n\ndef test_weird_input(mini):\n    print(\"[3] 畸形输入形态（C 的手写读取器要能忍）\")\n    cases = [\n        (\"6 3\\n1 2 4 5 -2 6\\n\", [6], \"标准两行\"),\n        (\"6 3 1 2 4 5 -2 6\", [6], \"全挤一行、末尾无换行\"),\n        (\"6\\n3\\n1 2 4 5 -2 6\\n\", [6], \"n 与 m 分两行\"),\n        (\"6 3\\n1\\n2\\n4\\n5\\n-2\\n6\\n\", [6], \"每个 x 一行\"),\n        (\"6 3\\r\\n1 2 4 5 -2 6\\r\\n\", [6], \"CRLF\"),\n        (\"\\n\\n6 3\\n\\n1 2 4 5 -2 6\\n\\n\\n\", [6], \"夹空行\"),\n        (\"   6   3   \\n   1  2  4  5  -2  6   \\n\", [6], \"多余空白\"),\n        (\"+6 +3\\n+1 2 4 5 -2 6\\n\", [6], \"正号\"),\n        (\"6 3\\n1 2 4 5 -2 6\\n6 3\\n1 2 4 5 -2 6\\n\", [6, 6], \"多组连排\"),\n        (\"1 1\\n7\\n\", [1], \"n=1\"),\n        (\"3 20\\n1 2 3\\n\", [3], \"m 上限\"),\n        (\"5 2\\n0 1 2 100 101\\n\", [5], \"剪中间大空隙\"),\n    ]\n    bad = 0\n    for (text, exp, why) in cases:\n        got, _ = c_solve(text, True)\n        if got != exp:\n            bad += 1\n            print(\"      X %s: got=%s exp=%s\" % (why, got, exp))\n    check(bad == 0, \"%d 种形态全过\" % len(cases))\n\n\ndef test_bad_input(mini):\n    print(\"[4] 非法输入要中止、不许错答\")\n    cases = [\n        (\"0 3\\n1 2 3\\n\", \"n=0\"),\n        (\"1001 3\\n1 2 3\\n\", \"n=1001\"),\n        (\"-3 2\\n1 2 3\\n\", \"n 为负\"),\n        (\"abc 2\\n1 2 3\\n\", \"n 非整数\"),\n        (\"3\\n1 2 3\\n\", \"缺 m\"),\n        (\"5 2\\n1 2 3\\n\", \"数据不足\"),\n    ]\n    bad = 0\n    for (text, why) in cases:\n        got, reason = c_solve(text, True)\n        if got != [] or reason is None:\n            bad += 1\n            print(\"      X %s: out=%s reason=%s\" % (why, got, reason))\n    check(bad == 0, \"%d 种非法输入全部中止且 stdout 零输出\" % len(cases))\n\n\ndef test_scale(mini):\n    print(\"[5] 大规模 n=1000\")\n    rng = random.Random(2718)\n    bad = 0\n    for _ in range(4):\n        n = 1000\n        m = rng.randint(1, 20)\n        x = rng.sample(range(-500000, 500000), n)\n        text = \"%d %d\\n%s\\n\" % (n, m, \" \".join(str(v) for v in x))\n        got, _ = c_solve(text, True)\n        want = feed(mini, n, m, x, \"interval\")\n        if got != [want]:\n            bad += 1\n            print(\"      X n=1000 m=%d: 转写=%s 本体=%s\" % (m, got, [want]))\n    check(bad == 0, \"n=1000 四组一致\")\n\n\ndef strip_c_comments(src):\n    \"\"\"把 C 源码里的注释替换成等长空白（保留换行），字符串字面量原样保留。\n\n    为什么必须剥：源码锚点若用朴素的子串查找，会被**注释里的词**误命中 ——\n    本文件注释里写着「不用 strtoll」和「strtoll 太宽松」，朴素匹配就会以为\n    代码里真的用了 strtoll。（Python 那边同理，所以那边一律用 ast 精确匹配，不用 grep。）\n    \"\"\"\n    out = []\n    i = 0\n    n = len(src)\n    while i < n:\n        c = src[i]\n        if c == \"/\" and i + 1 < n and src[i + 1] == \"*\":\n            j = src.find(\"*/\", i + 2)\n            j = n if j < 0 else j + 2\n            for k in range(i, j):\n                out.append(\"\\n\" if src[k] == \"\\n\" else \" \")\n            i = j\n        elif c == \"/\" and i + 1 < n and src[i + 1] == \"/\":\n            j = src.find(\"\\n\", i)\n            j = n if j < 0 else j\n            for k in range(i, j):\n                out.append(\" \")\n            i = j\n        elif c == '\"':\n            j = i + 1\n            while j < n and src[j] != '\"':\n                if src[j] == \"\\\\\":\n                    j += 1\n                j += 1\n            j = min(j + 1, n)\n            out.append(src[i:j])\n            i = j\n        else:\n            out.append(c)\n            i += 1\n    return \"\".join(out)\n\n\ndef test_c_source_anchors():\n    print(\"[6] interval_cover.c 源码锚点（防止文件被改坏 / 关键点被删）\")\n\n    # 先确认剥离器本身可靠 —— 否则下面的锚点检查就是装饰品（陷阱 20）\n    probe = ('int a; /*注释里的 strtoll 不该被发现*/\\n'\n             '// 行注释里的 qsort 也不该\\n'\n             'char *s = \"字符串里的 /* 不是注释\";\\n'\n             'long long b;\\n')\n    code_probe = strip_c_comments(probe)\n    check(\"strtoll\" not in code_probe and \"qsort\" not in code_probe\n          and \"long long\" in code_probe and \"long long b;\" in code_probe,\n          \"注释剥离器自检（注释里的词被剥掉、代码里的词留下）\")\n\n    src = open(CSRC, encoding=\"utf-8\").read()\n    code = strip_c_comments(src)          # ★ 所有锚点都在\"剥掉注释的代码\"上查\n    anchors = [\n        (\"long long\", \"答案用 64 位，防溢出\"),\n        ('printf(\"%lld\\\\n\"', \"输出走 long long 格式符\"),\n        (\"#define MODEL_INTERVAL 0\", \"判题口径开关默认 point（OJ 实测口径）\"),\n        (\"ungetc(c, stdin)\", \"读整数时把多读的字符放回\"),\n        (\"qsort(xs, (size_t)n, sizeof(long long), cmp_ll_asc)\", \"升序排 x\"),\n        (\"qsort(gaps, (size_t)(n - 1), sizeof(long long), cmp_ll_desc)\", \"降序排空隙\"),\n        (\"if (n_ll < 1 || n_ll > MAX_N)\", \"n 越界检查\"),\n        (\"return 0;\", \"越界时中止\"),\n        (\"fflush(stdout)\", \"每组立即刷出\"),\n    ]\n    forbidden = [\n        (\"strtoll\", \"陷阱 13：strtoll 解析太宽松\"),\n        (\"scanf(\\\"%d\\\"\", \"用 %d 装 long long 会溢出\"),\n        (\"gets(\", \"gets 已废弃且危险\"),\n    ]\n    bad = 0\n    for (needle, why) in anchors:\n        if needle not in code:\n            bad += 1\n            print(\"      X 缺少锚点: %s（%s）\" % (needle, why))\n    for (needle, why) in forbidden:\n        if needle in code:\n            bad += 1\n            print(\"      X 出现禁用写法: %s（%s）\" % (needle, why))\n    check(bad == 0, \"锚点 %d 条全在、禁用写法 %d 条全无（均已剥除注释）\"\n          % (len(anchors), len(forbidden)))\n\n    check(\"fprintf(stderr\" in code, \"错误走 stderr（不污染 stdout）\")\n\n\ndef main():\n    print(\"=\" * 70)\n    print(\"interval_cover.c 逐行转写核对\")\n    print(\"=\" * 70)\n    print(\"注：本机无 C 编译器，这里只核对**逻辑**，不核对语法 / 宏 / qsort 细节。\")\n\n    mini = load_module(MINI, \"interval_cover\")\n    test_anchors(mini)\n    test_random(mini)\n    test_weird_input(mini)\n    test_bad_input(mini)\n    test_scale(mini)\n    test_c_source_anchors()\n\n    print(\"=\" * 70)\n    if FAILS:\n        print(\"FAILED: %d 项没过\" % len(FAILS))\n        for f in FAILS:\n            print(\"   - \" + f)\n        return 1\n    print(\"OK: C 逐行转写 == interval_cover.py（锚定 / 随机 20000 组 / \"\n          \"畸形输入 12 种 / 非法输入 6 种 / n=1000）；interval_cover.c 源码锚点全在\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n"}, {"label": "验证脚本 verify_interval_cover_mutations.py", "file": "verify_interval_cover_mutations.py", "lang": "py", "stripped": "import ast\nimport importlib.util\nimport io\nimport os\nimport random\nimport shutil\nimport subprocess\nimport sys\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nMINI = os.path.join(HERE, \"interval_cover.py\")\nDETAILED = os.path.join(HERE, \"interval_cover_detailed.py\")\nANIM = os.path.join(HERE, \"interval_cover_animation.html\")\nNODE_VERIFY = os.path.join(HERE, \"verify_interval_cover_animation.js\")\nPY = sys.executable\n\nTMP = os.path.join(HERE, \"_mutation_tmp\")\nos.makedirs(TMP, exist_ok=True)\n\ndef load_module(path, name):\n    spec = importlib.util.spec_from_file_location(name, path)\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\n_verify_spec = importlib.util.spec_from_file_location(\n    \"verify_ic\", os.path.join(HERE, \"verify_interval_cover.py\"))\nverify = importlib.util.module_from_spec(_verify_spec)\n_verify_spec.loader.exec_module(verify)\n\ndef run_py(path, stdin_text):\n    p = subprocess.run([PY, path], input=stdin_text.encode(\"utf-8\"),\n                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n    out = p.stdout.decode(\"utf-8\", \"replace\").replace(\"\\r\\n\", \"\\n\")\n    err = p.stderr.decode(\"utf-8\", \"replace\").replace(\"\\r\\n\", \"\\n\")\n    return p.returncode, out, err\n\ndef det_algorithm(path):\n    try:\n        mod = load_module(path, \"mut_alg\")\n    except Exception:\n        return True\n    rng = random.Random(4242)\n    for model in (\"interval\", \"point\"):\n        for _ in range(300):\n            n = rng.randint(1, 9)\n            m = rng.randint(1, 6)\n            x = rng.sample(range(-15, 16), n)\n            try:\n                got = mod.min_length(list(x), m, model)\n            except Exception:\n                return True\n            if got != verify.brute_enumerate(x, m, model):\n                return True\n\n    for (x, m, model, exp, _why) in verify.ANCHORS:\n        try:\n            if mod.min_length(list(x), m, model) != exp:\n                return True\n        except Exception:\n            return True\n    return False\n\ndef det_ast(path):\n    try:\n        return len(verify.ast_check(path)) > 0\n    except SyntaxError:\n        return True\n\ndef det_gbk(path):\n    try:\n        return len(verify.gbk_check(path)) > 0\n    except SyntaxError:\n        return True\n\ndef det_newline(path):\n    rc, out, err = run_py(path, \"6 3\\n1 2 4 5 -2 6\\n\")\n    return not out.endswith(\"\\n\")\n\ndef det_stdout_clean(path):\n    rc, out, err = run_py(path, \"0 3\\n1 2 3\\n\")\n    return \"[!]\" in out\n\ndef det_abort_on_bad_n(path):\n    rc, out, err = run_py(path, \"0 3\\n1 2 3 4 5 6 7 8\\n\")\n    return out.strip() != \"\"\n\ndef det_reader_slope(path):\n    try:\n        mod = load_module(path, \"mut_reader\")\n    except Exception:\n        return True\n    K = 20000\n    dk = verify.make_tokens(K)\n    d4k = verify.make_tokens(4 * K)\n    try:\n        tk = verify.timed(mod.make_reader, dk, repeat=2)\n        t4k = verify.timed(mod.make_reader, d4k, repeat=1)\n    except Exception:\n        return True\n    if tk <= 0:\n        return True\n    return (t4k / tk) > 7.0\n\ndef det_detailed(path):\n    src = io.open(path, encoding=\"utf-8\").read()\n    flipped = os.path.join(TMP, os.path.basename(path).replace(\".py\", \"_flip.py\"))\n    for a, b in (('MODEL = \"point\"', 'MODEL = \"interval\"'),\n                 ('MODEL = \"interval\"', 'MODEL = \"point\"')):\n        if a in src:\n            io.open(flipped, \"w\", encoding=\"utf-8\").write(src.replace(a, b, 1))\n            break\n    else:\n        io.open(flipped, \"w\", encoding=\"utf-8\").write(src)\n\n    cases = [\"6 3\\n1 2 4 5 -2 6\\n\", \"3 2\\n1 2 3\\n\", \"4 2\\n1 2 10 11\\n\", \"2 1\\n-5 5\\n\",\n             \"1 1\\n7\\n\", \"3 5\\n1 2 3\\n\", \"5 2\\n0 1 2 100 101\\n\"]\n    try:\n        for v in (path, flipped):\n            for inp in cases:\n                rc, out, err = run_py(v, inp)\n                if \"***\" in out or \"自校未通过\" in err:\n                    return True\n        return False\n    finally:\n        if os.path.exists(flipped):\n            os.remove(flipped)\n\ndef det_node(path):\n    backup = ANIM + \".orig\"\n    shutil.copyfile(ANIM, backup)\n    try:\n        shutil.copyfile(path, ANIM)\n        p = subprocess.run([\"node\", NODE_VERIFY], cwd=HERE,\n                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n        return p.returncode != 0\n    finally:\n        shutil.copyfile(backup, ANIM)\n        os.remove(backup)\n\nMUTATIONS = [\n\n    (\"提交版\", \"span 少 +1\",\n     MINI, \"span = x[n - 1] + 1 - x[0]\", \"span = x[n - 1] - x[0]\", det_algorithm),\n    (\"提交版\", \"gap 忘了 -1\",\n     MINI, \"gaps = [x[i + 1] - x[i] - 1 for i in range(n - 1)]\",\n     \"gaps = [x[i + 1] - x[i] for i in range(n - 1)]\", det_algorithm),\n    (\"提交版\", \"剪最小的 m-1 个空隙（排序方向反了）\",\n     MINI, \"gaps.sort(reverse=True)\", \"gaps.sort()\", det_algorithm),\n    (\"提交版\", \"多剪一刀（k = m 而非 m-1）\",\n     MINI, \"    k = m - 1                                     # 最多剪 m-1 刀\",\n     \"    k = m\", det_algorithm),\n    (\"提交版\", \"k 不夹到 n-1（越界）\",\n     MINI, \"    if k > n - 1:                                 # 只有 n-1 个位置可剪\\n        k = n - 1\\n\",\n     \"\", det_algorithm),\n    (\"提交版\", \"忘记排序\",\n     MINI, \"    x.sort()\", \"    pass\", det_algorithm),\n    (\"提交版\", \"point 口径的 span 也写成 +1\",\n     MINI, '        span = x[n - 1] - x[0]\\n        gaps = [x[i + 1] - x[i] for i in range(n - 1)]',\n     '        span = x[n - 1] + 1 - x[0]\\n        gaps = [x[i + 1] - x[i] for i in range(n - 1)]',\n     det_algorithm),\n    (\"提交版\", \"point 口径的 gap 也减 1\",\n     MINI, \"        gaps = [x[i + 1] - x[i] for i in range(n - 1)]\",\n     \"        gaps = [x[i + 1] - x[i] - 1 for i in range(n - 1)]\", det_algorithm),\n    (\"提交版\", \"改用 sys.stdin.read()（铁律 1）\",\n     MINI, \"        while not buf:\\n            line = sys.stdin.readline()\",\n     \"        while not buf:\\n            line = sys.stdin.read().splitlines()[0] if sys.stdin.read() else ''\",\n     det_ast),\n    (\"提交版\", \"取 token 用 pop(0)（O(k^2) 悬崖）\",\n     MINI, \"        return buf.pop()\", \"        return buf.pop(0)\", det_reader_slope),\n    (\"提交版\", \"引入 f-string（老 OJ 直接 CE）\",\n     MINI, \"    cut = 0\\n    for i in range(k):\",\n     \"    cut = 0\\n    _dbg = f\\\"{len(gaps)}\\\"\\n    for i in range(k):\", det_ast),\n    (\"提交版\", \"改用 input()（老 OJ / 重定向都不稳）\",\n     MINI, \"    cut = 0\\n    for i in range(k):\",\n     \"    cut = 0\\n    _dbg = input()\\n    for i in range(k):\", det_ast),\n    (\"提交版\", \"stdout 输出丢掉行尾换行（铁律 4）\",\n     MINI, 'sys.stdout.write(\"%d\\\\n\" % min_length(x, m, MODEL))',\n     'sys.stdout.write(\"%d\" % min_length(x, m, MODEL))', det_newline),\n    (\"提交版\", \"错误信息走 stdout（铁律 3 / 陷阱 1）\",\n     MINI, 'sys.stderr.write(\"[!] n 越界: %s（应为 1 <= n <= %d，第 %d 组）\\\\n\"',\n     'sys.stdout.write(\"[!] n 越界: %s（应为 1 <= n <= %d，第 %d 组）\\\\n\"',\n     det_stdout_clean),\n    (\"提交版\", \"n 越界时 continue 而不是中止（铁律 6 / 陷阱 11）\",\n     MINI, '            sys.stderr.write(\"[!] n 越界: %s（应为 1 <= n <= %d，第 %d 组）\\\\n\"\\n                             % (n, MAX_N, case + 1))\\n            return',\n     '            sys.stderr.write(\"[!] n 越界: %s（应为 1 <= n <= %d，第 %d 组）\\\\n\"\\n                             % (n, MAX_N, case + 1))\\n            continue',\n     det_abort_on_bad_n),\n\n    (\"详细版\", \"剪最小的空隙（算法错，自校必须报）\",\n     DETAILED, \"    order = sorted(range(len(gaps)), key=lambda i: (-gaps[i], i))\",\n     \"    order = sorted(range(len(gaps)), key=lambda i: (gaps[i], i))\",\n     det_detailed),\n    (\"详细版\", \"span 少 +1（算法错，自校必须报）\",\n     DETAILED, \"        span = xs[n - 1] + 1 - xs[0]\",\n     \"        span = xs[n - 1] - xs[0]\", det_detailed),\n    (\"详细版\", \"线段的右端点没盖到区间右端（方案盖不住）\",\n     DETAILED, \"            right = xs[r] + 1\\n            length = right - left\",\n     \"            right = xs[r]\\n            length = right - left\", det_detailed),\n\n    (\"动画\", \"gap 忘了 -1\",\n     ANIM, \"    gaps.push(isPoint ? (sorted[i + 1] - sorted[i]) : (sorted[i + 1] - sorted[i] - 1));\",\n     \"    gaps.push(sorted[i + 1] - sorted[i]);\", det_node),\n    (\"动画\", \"剪最小的空隙\",\n     ANIM, \"  var chosen = order.slice(0, cuts).sort(function (a, b) { return a - b; });\",\n     \"  var chosen = order.slice(order.length - cuts).sort(function (a, b) { return a - b; });\",\n     det_node),\n    (\"动画\", \"SVG 的 fill 用 CSS 变量（无效值，会退回黑色）\",\n     ANIM, \"    var fill = C_INFO, stroke = C_INFO_FG;\",\n     \"    var fill = 'var(--info)', stroke = 'var(--info-fg)';\", det_node),\n    (\"动画\", \"中文里混进 ASCII 双引号（整个 script 会炸）\",\n     ANIM, \"  '第 1 步 / 原始数据：先把要盖住的单位区间摆出来。',\",\n     \"  '第 1 步 / 原始数据：先把要盖住的\\\"单位区间\\\"摆出来。',\", det_node),\n]\n\ndef main():\n    print(\"=\" * 70)\n    print(\"变异测试 —— 把源码故意改回错的，看断言抓不抓得到\")\n    print(\"=\" * 70)\n\n    ok = 0\n    missed = []\n    broken_anchor = []\n\n    for i, (group, name, target, old, new, detector) in enumerate(MUTATIONS, 1):\n        src = io.open(target, encoding=\"utf-8\").read()\n        if old not in src:\n            broken_anchor.append(group + \" / \" + name)\n            print(\"[%2d] %-8s %-34s  X 找不到锚点（脚本与源码脱节）\" % (i, group, name))\n            continue\n\n        mutated = src.replace(old, new, 1)\n        ext = os.path.splitext(target)[1]\n        tmp = os.path.join(TMP, \"mut_%02d%s\" % (i, ext))\n        io.open(tmp, \"w\", encoding=\"utf-8\").write(mutated)\n\n        try:\n            caught = detector(tmp)\n        except Exception as e:\n            caught = True\n            print(\"      （检测器抛异常，按抓住处理：%s）\" % e)\n        finally:\n            if os.path.exists(tmp):\n                os.remove(tmp)\n\n        if caught:\n            ok += 1\n            print(\"[%2d] %-8s %-34s  . 被抓住\" % (i, group, name))\n        else:\n            missed.append(group + \" / \" + name)\n            print(\"[%2d] %-8s %-34s  X 没抓住 —— 断言有漏洞\" % (i, group, name))\n\n    print(\"-\" * 70)\n    print(\"捕获率 %d/%d\" % (ok, len(MUTATIONS)))\n\n    if broken_anchor:\n        print(\"锚点失效 %d 条：%s\" % (len(broken_anchor), broken_anchor))\n    if missed:\n        print(\"漏网 %d 条：%s\" % (len(missed), missed))\n\n    print(\"-\" * 70)\n    print(\"还原检查：跑一遍 verify_interval_cover.py（源码未被改动）\")\n    p = subprocess.run([PY, os.path.join(HERE, \"verify_interval_cover.py\")],\n                       cwd=HERE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n    tail = p.stdout.decode(\"utf-8\", \"replace\").strip().splitlines()[-1:]\n    if p.returncode == 0:\n        print(\"  . 主验收脚本仍全绿：\" + (tail[0] if tail else \"\"))\n    else:\n        print(\"  X 主验收脚本挂了：\")\n        print(p.stdout.decode(\"utf-8\", \"replace\")[-1500:])\n\n    if os.path.isdir(TMP) and not os.listdir(TMP):\n        os.rmdir(TMP)\n\n    print(\"=\" * 70)\n    if missed or broken_anchor or p.returncode != 0:\n        print(\"FAILED\")\n        return 1\n    print(\"OK: 变异捕获率 %d/%d；还原后主验收脚本仍全绿\" % (ok, len(MUTATIONS)))\n    return 0\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n", "original": "# -*- coding: utf-8 -*-\n#\n# 单位区间覆盖 —— 变异测试（验收\"断言到底有没有牙齿\"）\n# =====================================================\n#\n# 思路（本仓库陷阱 20 / 26 / 29 的正面用法）：\n#   把源码**故意改回错的**，逐个跑检测器。**打不掉任何断言的变异 = 那个断言是装饰品**。\n#   反过来，某个变异若全绿通过，说明我对那种错法**根本没有防御**。\n#\n# 跑法：\n#     cd E:/沈云付算法/单位区间覆盖\n#     PYTHONIOENCODING=utf-8 python verify_interval_cover_mutations.py\n#\n# 期望：\n#     OK: 变异捕获率 22/22（提交版 15/15，详细版 3/3，动画 4/4）；\n#         还原后 verify_interval_cover.py 仍全绿\n#\n# 注意：本脚本只把变异体写成**临时文件**再删掉，绝不改动原始源码。\n\nimport ast\nimport importlib.util\nimport io\nimport os\nimport random\nimport shutil\nimport subprocess\nimport sys\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nMINI = os.path.join(HERE, \"interval_cover.py\")\nDETAILED = os.path.join(HERE, \"interval_cover_detailed.py\")\nANIM = os.path.join(HERE, \"interval_cover_animation.html\")\nNODE_VERIFY = os.path.join(HERE, \"verify_interval_cover_animation.js\")\nPY = sys.executable\n\nTMP = os.path.join(HERE, \"_mutation_tmp\")\nos.makedirs(TMP, exist_ok=True)\n\n\ndef load_module(path, name):\n    spec = importlib.util.spec_from_file_location(name, path)\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\n\n# 借用主验收脚本的独立实现与工具（它有 __main__ 保护，import 不会跑 main）\n_verify_spec = importlib.util.spec_from_file_location(\n    \"verify_ic\", os.path.join(HERE, \"verify_interval_cover.py\"))\nverify = importlib.util.module_from_spec(_verify_spec)\n_verify_spec.loader.exec_module(verify)\n\n\ndef run_py(path, stdin_text):\n    p = subprocess.run([PY, path], input=stdin_text.encode(\"utf-8\"),\n                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n    out = p.stdout.decode(\"utf-8\", \"replace\").replace(\"\\r\\n\", \"\\n\")\n    err = p.stderr.decode(\"utf-8\", \"replace\").replace(\"\\r\\n\", \"\\n\")\n    return p.returncode, out, err\n\n\n# =====================================================================\n# 检测器：每个返回 True 表示\"这个变异被抓到了\"\n# =====================================================================\n\ndef det_algorithm(path):\n    \"\"\"与暴力枚举对拍；算错、或直接崩，都算抓到。\"\"\"\n    try:\n        mod = load_module(path, \"mut_alg\")\n    except Exception:\n        return True                      # 载入就炸（语法错误等），当然算抓到\n    rng = random.Random(4242)\n    for model in (\"interval\", \"point\"):\n        for _ in range(300):\n            n = rng.randint(1, 9)\n            m = rng.randint(1, 6)\n            x = rng.sample(range(-15, 16), n)\n            try:\n                got = mod.min_length(list(x), m, model)\n            except Exception:\n                return True\n            if got != verify.brute_enumerate(x, m, model):\n                return True\n    # 顺带核锚定，防止变异只在罕见形状上暴露\n    for (x, m, model, exp, _why) in verify.ANCHORS:\n        try:\n            if mod.min_length(list(x), m, model) != exp:\n                return True\n        except Exception:\n            return True\n    return False\n\n\ndef det_ast(path):\n    \"\"\"AST 静态检查（f-string / input() / .buffer / 类型注解 / nonlocal / 海象）。\"\"\"\n    try:\n        return len(verify.ast_check(path)) > 0\n    except SyntaxError:\n        return True\n\n\ndef det_gbk(path):\n    try:\n        return len(verify.gbk_check(path)) > 0\n    except SyntaxError:\n        return True\n\n\ndef det_newline(path):\n    \"\"\"stdout 末尾必须有换行（铁律 4）。\"\"\"\n    rc, out, err = run_py(path, \"6 3\\n1 2 4 5 -2 6\\n\")\n    return not out.endswith(\"\\n\")\n\n\ndef det_stdout_clean(path):\n    \"\"\"错误信息必须走 stderr；stdout 里出现 [!] 就是污染。\"\"\"\n    rc, out, err = run_py(path, \"0 3\\n1 2 3\\n\")\n    return \"[!]\" in out\n\n\ndef det_abort_on_bad_n(path):\n    \"\"\"n 越界必须中止（铁律 6）；stdout 里冒出答案就是\"错答\"。\n\n    输入必须**足够长**：数据太短时，变异版（continue）会很快撞上\"数据不足\"再次中止，\n    反而把问题盖住 —— 这个坑第一版就踩了，用 \"0 3 / 1 2 3\" 三个 token 测不出来。\n    \"\"\"\n    rc, out, err = run_py(path, \"0 3\\n1 2 3 4 5 6 7 8\\n\")\n    return out.strip() != \"\"\n\n\ndef det_reader_slope(path):\n    \"\"\"读取器斜率：写坏了（pop(0)）就会超过 7。\"\"\"\n    try:\n        mod = load_module(path, \"mut_reader\")\n    except Exception:\n        return True\n    K = 20000\n    dk = verify.make_tokens(K)\n    d4k = verify.make_tokens(4 * K)\n    try:\n        tk = verify.timed(mod.make_reader, dk, repeat=2)\n        t4k = verify.timed(mod.make_reader, d4k, repeat=1)\n    except Exception:\n        return True\n    if tk <= 0:\n        return True\n    return (t4k / tk) > 7.0\n\n\ndef det_detailed(path):\n    \"\"\"详细版变异：**两种口径各跑一遍**，任一口径下自校报错即算抓到。\n\n    为什么必须跑两种口径：interval / point 是两个独立分支，默认口径只走其中一条。\n    仓库默认从 interval 切到 point 之后，针对 interval 分支的变异就\"碰不到\"了 ——\n    第一版因此假报「没抓住」。翻转 MODEL 再跑一遍，两个分支就都被覆盖。\n\n    判据用「自校报错」：详细版的 ①-⑤ 管账目自洽，⑥（小规模暴力复核）管最优性，\n    任一维度出问题都会打星星；再加上人工变异，这条链就是有牙齿的。\n    \"\"\"\n    src = io.open(path, encoding=\"utf-8\").read()\n    flipped = os.path.join(TMP, os.path.basename(path).replace(\".py\", \"_flip.py\"))\n    for a, b in (('MODEL = \"point\"', 'MODEL = \"interval\"'),\n                 ('MODEL = \"interval\"', 'MODEL = \"point\"')):\n        if a in src:\n            io.open(flipped, \"w\", encoding=\"utf-8\").write(src.replace(a, b, 1))\n            break\n    else:\n        io.open(flipped, \"w\", encoding=\"utf-8\").write(src)     # 找不到开关就原样复制\n\n    cases = [\"6 3\\n1 2 4 5 -2 6\\n\", \"3 2\\n1 2 3\\n\", \"4 2\\n1 2 10 11\\n\", \"2 1\\n-5 5\\n\",\n             \"1 1\\n7\\n\", \"3 5\\n1 2 3\\n\", \"5 2\\n0 1 2 100 101\\n\"]\n    try:\n        for v in (path, flipped):\n            for inp in cases:\n                rc, out, err = run_py(v, inp)\n                if \"***\" in out or \"自校未通过\" in err:\n                    return True\n        return False\n    finally:\n        if os.path.exists(flipped):\n            os.remove(flipped)\n\n\ndef det_node(path):\n    \"\"\"动画变异：跑 node 验证脚本，非 0 退出即抓到。\n\n    node 脚本读的是固定路径，所以临时把变异体换到正主位置上跑，跑完立刻还原。\n    （第一版这里多写了一行，把原始 HTML 又写回了变异文件、把变异抹掉了 ——\n      结果四条动画变异全部假报\"没抓住\"。）\n    \"\"\"\n    backup = ANIM + \".orig\"\n    shutil.copyfile(ANIM, backup)\n    try:\n        shutil.copyfile(path, ANIM)\n        p = subprocess.run([\"node\", NODE_VERIFY], cwd=HERE,\n                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n        return p.returncode != 0\n    finally:\n        shutil.copyfile(backup, ANIM)\n        os.remove(backup)\n\n\n# =====================================================================\n# 变异清单\n# =====================================================================\n\nMUTATIONS = [\n    # ---------------- 提交版 interval_cover.py ----------------\n    (\"提交版\", \"span 少 +1\",\n     MINI, \"span = x[n - 1] + 1 - x[0]\", \"span = x[n - 1] - x[0]\", det_algorithm),\n    (\"提交版\", \"gap 忘了 -1\",\n     MINI, \"gaps = [x[i + 1] - x[i] - 1 for i in range(n - 1)]\",\n     \"gaps = [x[i + 1] - x[i] for i in range(n - 1)]\", det_algorithm),\n    (\"提交版\", \"剪最小的 m-1 个空隙（排序方向反了）\",\n     MINI, \"gaps.sort(reverse=True)\", \"gaps.sort()\", det_algorithm),\n    (\"提交版\", \"多剪一刀（k = m 而非 m-1）\",\n     MINI, \"    k = m - 1                                     # 最多剪 m-1 刀\",\n     \"    k = m\", det_algorithm),\n    (\"提交版\", \"k 不夹到 n-1（越界）\",\n     MINI, \"    if k > n - 1:                                 # 只有 n-1 个位置可剪\\n        k = n - 1\\n\",\n     \"\", det_algorithm),\n    (\"提交版\", \"忘记排序\",\n     MINI, \"    x.sort()\", \"    pass\", det_algorithm),\n    (\"提交版\", \"point 口径的 span 也写成 +1\",\n     MINI, '        span = x[n - 1] - x[0]\\n        gaps = [x[i + 1] - x[i] for i in range(n - 1)]',\n     '        span = x[n - 1] + 1 - x[0]\\n        gaps = [x[i + 1] - x[i] for i in range(n - 1)]',\n     det_algorithm),\n    (\"提交版\", \"point 口径的 gap 也减 1\",\n     MINI, \"        gaps = [x[i + 1] - x[i] for i in range(n - 1)]\",\n     \"        gaps = [x[i + 1] - x[i] - 1 for i in range(n - 1)]\", det_algorithm),\n    (\"提交版\", \"改用 sys.stdin.read()（铁律 1）\",\n     MINI, \"        while not buf:\\n            line = sys.stdin.readline()\",\n     \"        while not buf:\\n            line = sys.stdin.read().splitlines()[0] if sys.stdin.read() else ''\",\n     det_ast),\n    (\"提交版\", \"取 token 用 pop(0)（O(k^2) 悬崖）\",\n     MINI, \"        return buf.pop()\", \"        return buf.pop(0)\", det_reader_slope),\n    (\"提交版\", \"引入 f-string（老 OJ 直接 CE）\",\n     MINI, \"    cut = 0\\n    for i in range(k):\",\n     \"    cut = 0\\n    _dbg = f\\\"{len(gaps)}\\\"\\n    for i in range(k):\", det_ast),\n    (\"提交版\", \"改用 input()（老 OJ / 重定向都不稳）\",\n     MINI, \"    cut = 0\\n    for i in range(k):\",\n     \"    cut = 0\\n    _dbg = input()\\n    for i in range(k):\", det_ast),\n    (\"提交版\", \"stdout 输出丢掉行尾换行（铁律 4）\",\n     MINI, 'sys.stdout.write(\"%d\\\\n\" % min_length(x, m, MODEL))',\n     'sys.stdout.write(\"%d\" % min_length(x, m, MODEL))', det_newline),\n    (\"提交版\", \"错误信息走 stdout（铁律 3 / 陷阱 1）\",\n     MINI, 'sys.stderr.write(\"[!] n 越界: %s（应为 1 <= n <= %d，第 %d 组）\\\\n\"',\n     'sys.stdout.write(\"[!] n 越界: %s（应为 1 <= n <= %d，第 %d 组）\\\\n\"',\n     det_stdout_clean),\n    (\"提交版\", \"n 越界时 continue 而不是中止（铁律 6 / 陷阱 11）\",\n     MINI, '            sys.stderr.write(\"[!] n 越界: %s（应为 1 <= n <= %d，第 %d 组）\\\\n\"\\n                             % (n, MAX_N, case + 1))\\n            return',\n     '            sys.stderr.write(\"[!] n 越界: %s（应为 1 <= n <= %d，第 %d 组）\\\\n\"\\n                             % (n, MAX_N, case + 1))\\n            continue',\n     det_abort_on_bad_n),\n\n    # ---------------- 详细版 ----------------\n    (\"详细版\", \"剪最小的空隙（算法错，自校必须报）\",\n     DETAILED, \"    order = sorted(range(len(gaps)), key=lambda i: (-gaps[i], i))\",\n     \"    order = sorted(range(len(gaps)), key=lambda i: (gaps[i], i))\",\n     det_detailed),\n    (\"详细版\", \"span 少 +1（算法错，自校必须报）\",\n     DETAILED, \"        span = xs[n - 1] + 1 - xs[0]\",\n     \"        span = xs[n - 1] - xs[0]\", det_detailed),\n    (\"详细版\", \"线段的右端点没盖到区间右端（方案盖不住）\",\n     DETAILED, \"            right = xs[r] + 1\\n            length = right - left\",\n     \"            right = xs[r]\\n            length = right - left\", det_detailed),\n\n    # ---------------- 动画 ----------------\n    (\"动画\", \"gap 忘了 -1\",\n     ANIM, \"    gaps.push(isPoint ? (sorted[i + 1] - sorted[i]) : (sorted[i + 1] - sorted[i] - 1));\",\n     \"    gaps.push(sorted[i + 1] - sorted[i]);\", det_node),\n    (\"动画\", \"剪最小的空隙\",\n     ANIM, \"  var chosen = order.slice(0, cuts).sort(function (a, b) { return a - b; });\",\n     \"  var chosen = order.slice(order.length - cuts).sort(function (a, b) { return a - b; });\",\n     det_node),\n    (\"动画\", \"SVG 的 fill 用 CSS 变量（无效值，会退回黑色）\",\n     ANIM, \"    var fill = C_INFO, stroke = C_INFO_FG;\",\n     \"    var fill = 'var(--info)', stroke = 'var(--info-fg)';\", det_node),\n    (\"动画\", \"中文里混进 ASCII 双引号（整个 script 会炸）\",\n     ANIM, \"  '第 1 步 / 原始数据：先把要盖住的单位区间摆出来。',\",\n     \"  '第 1 步 / 原始数据：先把要盖住的\\\"单位区间\\\"摆出来。',\", det_node),\n]\n\n\n# =====================================================================\n\ndef main():\n    print(\"=\" * 70)\n    print(\"变异测试 —— 把源码故意改回错的，看断言抓不抓得到\")\n    print(\"=\" * 70)\n\n    ok = 0\n    missed = []\n    broken_anchor = []\n\n    for i, (group, name, target, old, new, detector) in enumerate(MUTATIONS, 1):\n        src = io.open(target, encoding=\"utf-8\").read()\n        if old not in src:\n            broken_anchor.append(group + \" / \" + name)\n            print(\"[%2d] %-8s %-34s  X 找不到锚点（脚本与源码脱节）\" % (i, group, name))\n            continue\n\n        mutated = src.replace(old, new, 1)\n        ext = os.path.splitext(target)[1]\n        tmp = os.path.join(TMP, \"mut_%02d%s\" % (i, ext))\n        io.open(tmp, \"w\", encoding=\"utf-8\").write(mutated)\n\n        try:\n            caught = detector(tmp)\n        except Exception as e:\n            caught = True                     # 检测器自己炸了也算\"抓到了\"，但要说清楚\n            print(\"      （检测器抛异常，按抓住处理：%s）\" % e)\n        finally:\n            if os.path.exists(tmp):\n                os.remove(tmp)\n\n        if caught:\n            ok += 1\n            print(\"[%2d] %-8s %-34s  . 被抓住\" % (i, group, name))\n        else:\n            missed.append(group + \" / \" + name)\n            print(\"[%2d] %-8s %-34s  X 没抓住 —— 断言有漏洞\" % (i, group, name))\n\n    print(\"-\" * 70)\n    print(\"捕获率 %d/%d\" % (ok, len(MUTATIONS)))\n\n    if broken_anchor:\n        print(\"锚点失效 %d 条：%s\" % (len(broken_anchor), broken_anchor))\n    if missed:\n        print(\"漏网 %d 条：%s\" % (len(missed), missed))\n\n    # 还原检查：源码没被改动过，主验收脚本必须仍然全绿\n    print(\"-\" * 70)\n    print(\"还原检查：跑一遍 verify_interval_cover.py（源码未被改动）\")\n    p = subprocess.run([PY, os.path.join(HERE, \"verify_interval_cover.py\")],\n                       cwd=HERE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n    tail = p.stdout.decode(\"utf-8\", \"replace\").strip().splitlines()[-1:]\n    if p.returncode == 0:\n        print(\"  . 主验收脚本仍全绿：\" + (tail[0] if tail else \"\"))\n    else:\n        print(\"  X 主验收脚本挂了：\")\n        print(p.stdout.decode(\"utf-8\", \"replace\")[-1500:])\n\n    # 清理临时目录\n    if os.path.isdir(TMP) and not os.listdir(TMP):\n        os.rmdir(TMP)\n\n    print(\"=\" * 70)\n    if missed or broken_anchor or p.returncode != 0:\n        print(\"FAILED\")\n        return 1\n    print(\"OK: 变异捕获率 %d/%d；还原后主验收脚本仍全绿\" % (ok, len(MUTATIONS)))\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n"}];
